internal/recon/model.go:
// Package recon ingests bank payment events, validates proposed invoice
// matches, records human approval and posts balanced journal entries.
//
// The flow is ingest, propose, approve, post. Each write command runs in one
// database transaction. Retries cannot duplicate financial effects; delivery
// attempts and rejected suggestions remain recorded as evidence.
package recon

// Invoice is a receivable that a payment can settle.
type Invoice struct {
	TenantID    string `json:"tenant_id"`
	InvoiceID   string `json:"invoice_id"`
	Currency    string `json:"currency"`
	AmountMinor int64  `json:"amount_minor"`
	Status      string `json:"status"`
}

// Invoice statuses.
const (
	InvoiceOpen    = "open"
	InvoiceSettled = "settled"
)

// BankEvent is one webhook delivery from a bank-feed provider. Amounts are
// integer minor units, for example pence.
type BankEvent struct {
	TenantID      string `json:"tenant_id"`
	Provider      string `json:"provider"`
	EventID       string `json:"event_id"`
	TransactionID string `json:"transaction_id"`
	Currency      string `json:"currency"`
	AmountMinor   int64  `json:"amount_minor"`
	Reference     string `json:"reference"`
}

// IngestOutcome says what happened to a delivery.
type IngestOutcome string

// Ingest outcomes. Conflicts are returned as errors, not outcomes.
const (
	// The event and its transaction were new.
	Accepted IngestOutcome = "accepted"
	// The same event was delivered again with identical content.
	DuplicateEvent IngestOutcome = "duplicate_event"
	// A new event ID described a transaction we already hold.
	DuplicateTransaction IngestOutcome = "duplicate_transaction"
)

// IngestResult is returned by Service.Ingest.
type IngestResult struct {
	Outcome   IngestOutcome `json:"outcome"`
	PaymentID int64         `json:"payment_id"`
}

// ProposalInput is a model's suggested match. It is untrusted.
type ProposalInput struct {
	TenantID      string  `json:"tenant_id"`
	TransactionID string  `json:"transaction_id"`
	InvoiceID     string  `json:"invoice_id"`
	Confidence    float64 `json:"confidence"`
}

// Proposal statuses.
const (
	ProposalOpen       = "open"
	ProposalRejected   = "rejected"
	ProposalSuperseded = "superseded"
	ProposalPosted     = "posted"
)

// Proposal is a stored suggestion with the result of its deterministic checks.
type Proposal struct {
	ID            int64   `json:"id"`
	TenantID      string  `json:"tenant_id"`
	TransactionID string  `json:"transaction_id"`
	InvoiceID     string  `json:"invoice_id"`
	Confidence    float64 `json:"confidence"`
	// Fingerprint identifies the exact content. A reviewer approves a
	// fingerprint, not just an ID.
	Fingerprint string  `json:"fingerprint"`
	PaymentID   *int64  `json:"payment_id,omitempty"`
	Checks      []Check `json:"checks"`
	Status      string  `json:"status"`
	Supersedes  *int64  `json:"supersedes,omitempty"`
	CreatedAt   string  `json:"created_at"`
	// Replayed is true when an identical proposal already existed.
	Replayed bool `json:"replayed"`
}

// ApprovalRequest is a reviewer's explicit decision about one proposal.
type ApprovalRequest struct {
	ProposalID int64
	// Fingerprint is the proposal content the reviewer looked at.
	Fingerprint string
	// Reviewer is a simulated identity. See the README for production auth.
	Reviewer string
}

// Approval is a recorded human decision.
type Approval struct {
	ID                  int64  `json:"id"`
	ProposalID          int64  `json:"proposal_id"`
	ProposalFingerprint string `json:"proposal_fingerprint"`
	Reviewer            string `json:"reviewer"`
	ApprovedAt          string `json:"approved_at"`
	Replayed            bool   `json:"replayed"`
}

// Ledger accounts used by this exercise.
const (
	AccountBank               = "bank"
	AccountAccountsReceivable = "accounts_receivable"
)

// JournalLine is one side of a journal entry.
type JournalLine struct {
	Account     string `json:"account"`
	DebitMinor  int64  `json:"debit_minor"`
	CreditMinor int64  `json:"credit_minor"`
}

// Journal is a posted entry and its lines.
type Journal struct {
	ID         int64         `json:"id"`
	TenantID   string        `json:"tenant_id"`
	PaymentID  int64         `json:"payment_id"`
	InvoiceID  string        `json:"invoice_id"`
	ProposalID int64         `json:"proposal_id"`
	ApprovalID int64         `json:"approval_id"`
	Currency   string        `json:"currency"`
	Memo       string        `json:"memo"`
	PostedAt   string        `json:"posted_at"`
	Lines      []JournalLine `json:"lines"`
	// Replayed is true when this call found the journal already posted.
	Replayed bool `json:"replayed"`
}

internal/recon/parse.go:
package recon

import (
	"bytes"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"errors"
	"io"
	"math"
	"regexp"
)

var currencyCode = regexp.MustCompile(`^[A-Z]{3}$`)

// The wire structs use pointers so a missing field is distinguishable from a
// zero value. Nothing is coerced: "12000" or 12000.5 for amount_minor is
// rejected, not converted.
type bankEventWire struct {
	TenantID      *string `json:"tenant_id"`
	Provider      *string `json:"provider"`
	EventID       *string `json:"event_id"`
	TransactionID *string `json:"transaction_id"`
	Currency      *string `json:"currency"`
	AmountMinor   *int64  `json:"amount_minor"`
	Reference     *string `json:"reference"`
}

type proposalWire struct {
	TenantID      *string  `json:"tenant_id"`
	TransactionID *string  `json:"transaction_id"`
	InvoiceID     *string  `json:"invoice_id"`
	Confidence    *float64 `json:"confidence"`
}

// ParseBankEvent strictly decodes and validates one provider payload.
func ParseBankEvent(raw []byte) (BankEvent, error) {
	var wire bankEventWire
	if err := decodeStrict(raw, &wire); err != nil {
		return BankEvent{}, invalid("malformed_event", "%v", err)
	}
	fields := []struct {
		name  string
		value *string
	}{
		{"tenant_id", wire.TenantID},
		{"provider", wire.Provider},
		{"event_id", wire.EventID},
		{"transaction_id", wire.TransactionID},
		{"currency", wire.Currency},
	}
	for _, field := range fields {
		if field.value == nil || *field.value == "" {
			return BankEvent{}, invalid("missing_field", "%s is required", field.name)
		}
	}
	// An empty reference is legitimate; only its absence is malformed.
	if wire.Reference == nil {
		return BankEvent{}, invalid("missing_field", "reference is required")
	}
	if wire.AmountMinor == nil {
		return BankEvent{}, invalid("missing_field", "amount_minor is required")
	}
	if !currencyCode.MatchString(*wire.Currency) {
		return BankEvent{}, invalid("invalid_currency", "currency %q is not a three-letter ISO code", *wire.Currency)
	}
	// Outgoing payments and refunds are out of scope for this service.
	if *wire.AmountMinor <= 0 {
		return BankEvent{}, invalid("invalid_amount", "amount_minor must be a positive incoming amount, got %d", *wire.AmountMinor)
	}
	return BankEvent{
		TenantID:      *wire.TenantID,
		Provider:      *wire.Provider,
		EventID:       *wire.EventID,
		TransactionID: *wire.TransactionID,
		Currency:      *wire.Currency,
		AmountMinor:   *wire.AmountMinor,
		Reference:     *wire.Reference,
	}, nil
}

// ParseProposal strictly decodes and validates a model suggestion. It checks
// shape only. Whether the match is acceptable is decided by evaluateChecks.
func ParseProposal(raw []byte) (ProposalInput, error) {
	var wire proposalWire
	if err := decodeStrict(raw, &wire); err != nil {
		return ProposalInput{}, invalid("malformed_proposal", "%v", err)
	}
	fields := []struct {
		name  string
		value *string
	}{
		{"tenant_id", wire.TenantID},
		{"transaction_id", wire.TransactionID},
		{"invoice_id", wire.InvoiceID},
	}
	for _, field := range fields {
		if field.value == nil || *field.value == "" {
			return ProposalInput{}, invalid("missing_field", "%s is required", field.name)
		}
	}
	if wire.Confidence == nil {
		return ProposalInput{}, invalid("missing_field", "confidence is required")
	}
	if c := *wire.Confidence; math.IsNaN(c) || c < 0 || c > 1 {
		return ProposalInput{}, invalid("invalid_confidence", "confidence must be between 0 and 1, got %v", c)
	}
	confidence := *wire.Confidence
	if confidence == 0 {
		// SQLite stores -0 as 0, which would change the fingerprint on the
		// way back out. Both mean "no confidence".
		confidence = 0
	}
	return ProposalInput{
		TenantID:      *wire.TenantID,
		TransactionID: *wire.TransactionID,
		InvoiceID:     *wire.InvoiceID,
		Confidence:    confidence,
	}, nil
}

func decodeStrict(raw []byte, dst any) error {
	decoder := json.NewDecoder(bytes.NewReader(raw))
	decoder.DisallowUnknownFields()
	if err := decoder.Decode(dst); err != nil {
		return err
	}
	if err := decoder.Decode(&struct{}{}); !errors.Is(err, io.EOF) {
		return errors.New("unexpected data after the JSON object")
	}
	return nil
}

// Fingerprints hash a fixed struct, not the raw payload, so key order and
// whitespace in a redelivery do not count as a change. The version prefix
// lets the definition change later without colliding with old hashes.

// eventFingerprint covers everything the event asserts. Any difference under
// the same event ID is a conflict, including the reference: a provider that
// reuses an ID for different content is a problem a person should see.
func eventFingerprint(e BankEvent) string {
	return fingerprint("event.v1", e)
}

// paymentFingerprint covers only the financial facts of the transaction, so a
// second event ID for the same transaction is recognised even if its
// reference text differs.
func paymentFingerprint(e BankEvent) string {
	return fingerprint("payment.v1", struct {
		TenantID      string `json:"tenant_id"`
		Provider      string `json:"provider"`
		TransactionID string `json:"transaction_id"`
		Currency      string `json:"currency"`
		AmountMinor   int64  `json:"amount_minor"`
	}{e.TenantID, e.Provider, e.TransactionID, e.Currency, e.AmountMinor})
}

// proposalFingerprint covers the whole suggestion, confidence included. If
// the model re-scores the same match, the reviewer has not seen the new
// version, so it needs a fresh approval.
func proposalFingerprint(p ProposalInput) string {
	return fingerprint("proposal.v1", p)
}

func fingerprint(version string, value any) string {
	encoded, err := json.Marshal(value)
	if err != nil {
		// The inputs are plain structs of strings and numbers.
		panic("fingerprint: " + err.Error())
	}
	sum := sha256.Sum256(append([]byte(version+"\n"), encoded...))
	return hex.EncodeToString(sum[:])
}

internal/db/db.go:
// Package db opens the SQLite database and applies the schema.
package db

import (
	"context"
	"database/sql"
	_ "embed"
	"fmt"
	"net/url"
	"strings"

	_ "modernc.org/sqlite"
)

//go:embed schema.sql
var schema string

// Open opens (or creates) the database at path and applies the schema.
//
// Write transactions start with BEGIN IMMEDIATE, so a writer takes the
// database write lock before it reads anything. Read-only transactions use a
// plain BEGIN and never block writers. Two processes posting the same
// payment therefore run one after the other, and the second sees the first's
// committed journal. synchronous=FULL makes a commit durable before it
// returns, which is what the crash-recovery guarantee relies on.
func Open(ctx context.Context, path string) (*sql.DB, error) {
	query := url.Values{}
	query.Add("_pragma", "foreign_keys(1)")
	query.Add("_pragma", "busy_timeout(10000)")
	query.Add("_pragma", "journal_mode(WAL)")
	query.Add("_pragma", "synchronous(FULL)")
	query.Set("_txlock", "immediate")

	// SQLite decodes the path as a URI, so characters with meaning there
	// must be escaped.
	escaped := strings.NewReplacer("%", "%25", "?", "%3f", "#", "%23").Replace(path)
	conn, err := sql.Open("sqlite", "file:"+escaped+"?"+query.Encode())
	if err != nil {
		return nil, fmt.Errorf("open %s: %w", path, err)
	}
	if _, err := conn.ExecContext(ctx, schema); err != nil {
		conn.Close()
		return nil, fmt.Errorf("apply schema: %w", err)
	}
	return conn, nil
}

internal/recon/errors.go:
package recon

import (
	"errors"
	"fmt"
)

// Kind classifies a domain error so callers can react without parsing text.
type Kind string

// Error kinds.
const (
	// The input was malformed. Nothing was recorded.
	KindInvalid Kind = "invalid"
	// The input contradicts something already recorded.
	KindConflict Kind = "conflict"
	// The request was understood but refused by a deterministic rule.
	KindRejected Kind = "rejected"
	// A referenced record does not exist.
	KindNotFound Kind = "not_found"
)

// Error is returned for every expected failure. Reason is a stable,
// machine-readable code.
type Error struct {
	Kind   Kind    `json:"kind"`
	Reason string  `json:"reason"`
	Detail string  `json:"detail"`
	Checks []Check `json:"checks,omitempty"`
}

func (e *Error) Error() string {
	return fmt.Sprintf("%s: %s: %s", e.Kind, e.Reason, e.Detail)
}

// IsKind reports whether err is a domain Error of the given kind.
func IsKind(err error, kind Kind) bool {
	var domainErr *Error
	return errors.As(err, &domainErr) && domainErr.Kind == kind
}

// Reason returns the reason code of a domain Error, or "" for any other error.
func Reason(err error) string {
	var domainErr *Error
	if errors.As(err, &domainErr) {
		return domainErr.Reason
	}
	return ""
}

func invalid(reason, format string, args ...any) *Error {
	return &Error{Kind: KindInvalid, Reason: reason, Detail: fmt.Sprintf(format, args...)}
}

func conflict(reason, format string, args ...any) *Error {
	return &Error{Kind: KindConflict, Reason: reason, Detail: fmt.Sprintf(format, args...)}
}

func rejected(reason, format string, args ...any) *Error {
	return &Error{Kind: KindRejected, Reason: reason, Detail: fmt.Sprintf(format, args...)}
}

func notFound(reason, format string, args ...any) *Error {
	return &Error{Kind: KindNotFound, Reason: reason, Detail: fmt.Sprintf(format, args...)}
}

// keepEvidence marks a domain error whose evidence rows (a delivery record or
// an audit event) were written in the current transaction. The transaction
// commits those rows and then returns the wrapped error. Rejection paths never
// write ledger rows before returning, so committing cannot leak a partial
// posting.
type keepEvidence struct{ err *Error }

func (k keepEvidence) Error() string { return k.err.Error() }

internal/recon/checks.go:
package recon

import "fmt"

// Check is the result of one deterministic rule applied to a proposal.
type Check struct {
	Name   string `json:"name"`
	Passed bool   `json:"passed"`
	Detail string `json:"detail"`
}

// Check names. They are stored with each proposal, so treat them as stable.
const (
	CheckPaymentExists   = "payment_exists_for_tenant"
	CheckPaymentUnique   = "payment_unambiguous"
	CheckPaymentUnposted = "payment_not_yet_posted"
	CheckInvoiceExists   = "invoice_exists_for_tenant"
	CheckInvoiceOpen     = "invoice_open"
	CheckCurrency        = "currency_matches"
	CheckAmount          = "amount_matches_in_full"
)

// matchFacts is everything the checks may look at. It is loaded inside the
// same transaction that acts on the result, so the facts cannot go stale
// between checking and posting.
type matchFacts struct {
	proposal ProposalInput
	// payments holds every payment in the proposal's tenant with the
	// proposal's transaction ID. Usually zero or one.
	payments []payment
	// posted is true when payments[0] already has a journal entry.
	posted  bool
	invoice *Invoice
}

// evaluateChecks applies every rule and reports each result, passing or not,
// so a reviewer sees the complete picture. Confidence is deliberately absent:
// it can rank suggestions for review, but it never authorises anything.
//
// Every lookup that produced matchFacts was scoped to the proposal's tenant,
// so a record from another tenant can only show up here as "not found".
func evaluateChecks(facts matchFacts) []Check {
	p := facts.proposal
	checks := make([]Check, 0, 7)
	add := func(name string, passed bool, format string, args ...any) {
		checks = append(checks, Check{Name: name, Passed: passed, Detail: fmt.Sprintf(format, args...)})
	}

	var pay *payment
	switch len(facts.payments) {
	case 0:
		add(CheckPaymentExists, false, "no payment %s in tenant %s", p.TransactionID, p.TenantID)
	case 1:
		pay = &facts.payments[0]
		add(CheckPaymentExists, true, "payment %d (%s %s)", pay.id, pay.provider, pay.transactionID)
		add(CheckPaymentUnique, true, "one payment has transaction ID %s", p.TransactionID)
	default:
		add(CheckPaymentExists, true, "%d payments have transaction ID %s", len(facts.payments), p.TransactionID)
		add(CheckPaymentUnique, false, "transaction ID %s is used by %d providers, and the proposal does not say which", p.TransactionID, len(facts.payments))
	}
	if pay != nil {
		if facts.posted {
			add(CheckPaymentUnposted, false, "payment %d already has a journal entry", pay.id)
		} else {
			add(CheckPaymentUnposted, true, "payment %d has no journal entry", pay.id)
		}
	}

	inv := facts.invoice
	if inv == nil {
		add(CheckInvoiceExists, false, "no invoice %s in tenant %s", p.InvoiceID, p.TenantID)
	} else {
		add(CheckInvoiceExists, true, "invoice %s", inv.InvoiceID)
		add(CheckInvoiceOpen, inv.Status == InvoiceOpen, "invoice status is %s", inv.Status)
	}

	if pay != nil && inv != nil {
		add(CheckCurrency, pay.currency == inv.Currency, "payment %s, invoice %s", pay.currency, inv.Currency)
		add(CheckAmount, pay.amountMinor == inv.AmountMinor, "payment %d, invoice %d", pay.amountMinor, inv.AmountMinor)
	}
	return checks
}

// allPassed is true when no check failed. Checks that depend on a missing
// record are skipped, but the missing record is itself a failed check.
func allPassed(checks []Check) bool {
	for _, check := range checks {
		if !check.Passed {
			return false
		}
	}
	return len(checks) > 0
}

func failedChecks(checks []Check) []Check {
	var failed []Check
	for _, check := range checks {
		if !check.Passed {
			failed = append(failed, check)
		}
	}
	return failed
}

internal/recon/service.go:
package recon

import (
	"context"
	"database/sql"
	"errors"
	"fmt"
	"strings"
	"time"
)

// Options configures a Service.
type Options struct {
	// Now returns the current time. It defaults to time.Now.
	Now func() time.Time
	// AfterPostCommit runs after a posting transaction commits and before
	// Post returns. If it returns an error, Post returns that error instead of
	// the journal. Tests and the CLI use it to simulate the worst-timed crash:
	// the journal is durable, but the caller never hears that it succeeded.
	AfterPostCommit func() error
}

// Service runs the reconciliation flow against one database. It holds no
// state of its own, so any number of Services, in one process or many, can
// share a database.
type Service struct {
	db              *sql.DB
	now             func() time.Time
	afterPostCommit func() error
}

// New returns a Service backed by db, which must come from db.Open.
func New(db *sql.DB, opts Options) *Service {
	now := opts.Now
	if now == nil {
		now = time.Now
	}
	return &Service{db: db, now: now, afterPostCommit: opts.AfterPostCommit}
}

const systemActor = "system"

// LoadInvoices inserts fixture invoices. Loading the same invoice twice is a
// no-op; loading different content under an existing ID is a conflict.
func (s *Service) LoadInvoices(ctx context.Context, invoices []Invoice) error {
	return s.inTx(ctx, func(tx *sql.Tx) error {
		for _, inv := range invoices {
			if err := validateInvoice(inv); err != nil {
				return err
			}
			existing, err := findInvoice(ctx, tx, inv.TenantID, inv.InvoiceID)
			if err != nil {
				return err
			}
			if existing != nil {
				if *existing != inv {
					return conflict("invoice_content_changed", "invoice %s/%s already exists with different content", inv.TenantID, inv.InvoiceID)
				}
				continue
			}
			if _, err := tx.ExecContext(ctx, `
				INSERT INTO invoices (tenant_id, invoice_id, currency, amount_minor, status) VALUES (?, ?, ?, ?, ?)`,
				inv.TenantID, inv.InvoiceID, inv.Currency, inv.AmountMinor, inv.Status); err != nil {
				return err
			}
		}
		return nil
	})
}

// Ingest records one provider delivery.
//
// A repeated delivery of the same event, or a new event ID for a transaction
// we already hold, returns the existing payment and creates nothing new. An
// event ID or transaction that comes back with different content is recorded
// as a conflict delivery and returned as a KindConflict error.
func (s *Service) Ingest(ctx context.Context, raw []byte) (IngestResult, error) {
	event, err := ParseBankEvent(raw)
	if err != nil {
		return IngestResult{}, err
	}
	eventFP := eventFingerprint(event)
	paymentFP := paymentFingerprint(event)
	now := s.timestamp()

	var result IngestResult
	err = s.inTx(ctx, func(tx *sql.Tx) error {
		deliver := func(outcome string, paymentID *int64) error {
			return insertDelivery(ctx, tx, event, outcome, eventFP, raw, paymentID, now)
		}

		existing, seen, err := findEvent(ctx, tx, event.Provider, event.EventID)
		if err != nil {
			return err
		}
		if seen && existing.fingerprint != eventFP {
			if existing.event.TenantID != event.TenantID {
				// Say nothing about the other tenant's event, and keep this
				// delivery out of that tenant's trail.
				if err := deliver("event_conflict", nil); err != nil {
					return err
				}
				return keepEvidence{conflict("event_content_changed",
					"event %s/%s was already received with different content", event.Provider, event.EventID)}
			}
			if err := deliver("event_conflict", existing.paymentID); err != nil {
				return err
			}
			return keepEvidence{conflict("event_content_changed",
				"event %s/%s was already received with different content: %s",
				event.Provider, event.EventID, describeChanges(existing.event, event))}
		}

		if seen && existing.accepted {
			result = IngestResult{Outcome: DuplicateEvent, PaymentID: *existing.paymentID}
			return deliver(string(DuplicateEvent), existing.paymentID)
		}

		pay, known, err := findPayment(ctx, tx, event.Provider, event.TransactionID)
		if err != nil {
			return err
		}
		if known {
			if pay.fingerprint == paymentFP {
				if err := insertEvent(ctx, tx, event, eventFP, raw, pay.id, now); err != nil {
					return err
				}
				result = IngestResult{Outcome: DuplicateTransaction, PaymentID: pay.id}
				return deliver(string(DuplicateTransaction), &pay.id)
			}
			if pay.tenantID != event.TenantID {
				if err := deliver("transaction_conflict", nil); err != nil {
					return err
				}
				return keepEvidence{conflict("transaction_content_changed",
					"transaction %s/%s is already recorded with different content", event.Provider, event.TransactionID)}
			}
			if err := deliver("transaction_conflict", &pay.id); err != nil {
				return err
			}
			return keepEvidence{conflict("transaction_content_changed",
				"transaction %s/%s is already held as %s %d, but event %s says %s %d",
				event.Provider, event.TransactionID, pay.currency, pay.amountMinor,
				event.EventID, event.Currency, event.AmountMinor)}
		}

		paymentID, err := insertPayment(ctx, tx, event, paymentFP, now)
		if err != nil {
			return err
		}
		if err := insertEvent(ctx, tx, event, eventFP, raw, paymentID, now); err != nil {
			return err
		}
		result = IngestResult{Outcome: Accepted, PaymentID: paymentID}
		return deliver(string(Accepted), &paymentID)
	})
	return result, err
}

// Propose records a model's suggested match and runs the deterministic
// checks against it.
//
// The proposal is always stored and returned, so a reviewer can see what the
// model suggested. If any check fails, it is stored as rejected and Propose
// also returns a KindRejected error listing the failures. If it passes, it
// becomes the payment's open proposal and supersedes any earlier one.
// Submitting identical content again returns the existing open or posted
// proposal.
func (s *Service) Propose(ctx context.Context, raw []byte) (Proposal, error) {
	input, err := ParseProposal(raw)
	if err != nil {
		return Proposal{}, err
	}
	fp := proposalFingerprint(input)
	now := s.timestamp()

	var result Proposal
	err = s.inTx(ctx, func(tx *sql.Tx) error {
		existing, live, err := liveProposalByFingerprint(ctx, tx, fp)
		if err != nil {
			return err
		}
		if live {
			existing.Replayed = true
			result = existing
			return nil
		}

		facts, err := loadFacts(ctx, tx, input)
		if err != nil {
			return err
		}
		proposal := Proposal{
			TenantID:      input.TenantID,
			TransactionID: input.TransactionID,
			InvoiceID:     input.InvoiceID,
			Confidence:    input.Confidence,
			Fingerprint:   fp,
			Checks:        evaluateChecks(facts),
			Status:        ProposalRejected,
			CreatedAt:     now,
		}
		if len(facts.payments) == 1 {
			proposal.PaymentID = &facts.payments[0].id
		}

		if allPassed(proposal.Checks) {
			proposal.Status = ProposalOpen
			previous, hasPrevious, err := openProposalForPayment(ctx, tx, *proposal.PaymentID)
			if err != nil {
				return err
			}
			if hasPrevious {
				// Closing the old proposal also strands any approval it had,
				// because Post only accepts approvals of open proposals.
				if err := moveProposal(ctx, tx, previous.ID, ProposalOpen, ProposalSuperseded); err != nil {
					return err
				}
				proposal.Supersedes = &previous.ID
			}
		}

		proposal.ID, err = insertProposal(ctx, tx, proposal)
		if err != nil {
			return err
		}
		result = proposal
		if proposal.Status == ProposalRejected {
			return keepEvidence{&Error{
				Kind:   KindRejected,
				Reason: "checks_failed",
				Detail: fmt.Sprintf("proposal %d failed %d check(s)", proposal.ID, len(failedChecks(proposal.Checks))),
				Checks: failedChecks(proposal.Checks),
			}}
		}
		return nil
	})
	return result, err
}

// Approve records a reviewer's decision about one exact proposal.
//
// The reviewer must quote the fingerprint of the proposal they looked at. If
// the proposal is no longer open, or its checks no longer pass, the approval
// is refused and the refusal is audited. Repeating an eligible approval
// returns the original decision; a posted proposal also replays for recovery.
func (s *Service) Approve(ctx context.Context, req ApprovalRequest) (Approval, error) {
	reviewer := strings.TrimSpace(req.Reviewer)
	switch {
	case req.ProposalID <= 0:
		return Approval{}, invalid("missing_field", "proposal ID is required")
	case req.Fingerprint == "":
		return Approval{}, invalid("missing_field", "the fingerprint of the reviewed proposal is required")
	case reviewer == "":
		return Approval{}, invalid("missing_field", "reviewer is required")
	case strings.EqualFold(reviewer, systemActor):
		return Approval{}, invalid("reserved_reviewer", "%q is reserved for automated actions and cannot approve", systemActor)
	}
	now := s.timestamp()
	subject := fmt.Sprintf("proposal:%d", req.ProposalID)

	var result Approval
	err := s.inTx(ctx, func(tx *sql.Tx) error {
		refuse := func(e *Error) error {
			if err := insertAudit(ctx, tx, "approval_refused", reviewer, subject, e, now); err != nil {
				return err
			}
			return keepEvidence{e}
		}

		proposal, exists, err := getProposal(ctx, tx, req.ProposalID)
		if err != nil {
			return err
		}
		if !exists {
			return notFound("proposal_not_found", "proposal %d does not exist", req.ProposalID)
		}
		if req.Fingerprint != proposal.Fingerprint {
			return refuse(rejected("fingerprint_mismatch",
				"reviewed content %s does not match proposal %d (%s)", req.Fingerprint, proposal.ID, proposal.Fingerprint))
		}

		existing, approved, err := approvalForProposal(ctx, tx, proposal.ID)
		if err != nil {
			return err
		}
		// Completed postings can replay their approval during crash recovery;
		// every unposted decision must still be eligible for approval.
		if proposal.Status != ProposalOpen && !(approved && proposal.Status == ProposalPosted) {
			return refuse(rejected("proposal_not_open", "proposal %d is %s", proposal.ID, proposal.Status))
		}
		if proposal.Status == ProposalOpen {
			if _, failed, err := currentFacts(ctx, tx, proposal); err != nil {
				return err
			} else if failed != nil {
				return refuse(failed)
			}
		}
		if approved {
			existing.Replayed = true
			result = existing
			if existing.Reviewer == reviewer {
				return nil
			}
			// The first decision stands; record that someone else also tried.
			return insertAudit(ctx, tx, "approval_already_given", reviewer, subject,
				map[string]any{"approval_id": existing.ID, "approved_by": existing.Reviewer}, now)
		}

		result = Approval{
			ProposalID:          proposal.ID,
			ProposalFingerprint: proposal.Fingerprint,
			Reviewer:            reviewer,
			ApprovedAt:          now,
		}
		result.ID, err = insertApproval(ctx, tx, result)
		if err != nil {
			return err
		}
		return insertAudit(ctx, tx, "approved", reviewer, subject, result, now)
	})
	return result, err
}

// Post turns an approval into a balanced journal entry and settles the
// invoice, all in one transaction.
//
// Everything the approval relied on is checked again inside the posting
// transaction: the proposal is unchanged and still open, and every check
// still passes. Calling Post again for an approval that already posted
// returns the existing journal with Replayed set, which is how a caller
// recovers after a crash or a lost response.
func (s *Service) Post(ctx context.Context, approvalID int64) (Journal, error) {
	if approvalID <= 0 {
		return Journal{}, invalid("missing_field", "approval ID is required")
	}
	now := s.timestamp()
	subject := fmt.Sprintf("approval:%d", approvalID)

	var result Journal
	err := s.inTx(ctx, func(tx *sql.Tx) error {
		refuse := func(e *Error) error {
			if err := insertAudit(ctx, tx, "posting_refused", systemActor, subject, e, now); err != nil {
				return err
			}
			return keepEvidence{e}
		}

		approval, exists, err := getApproval(ctx, tx, approvalID)
		if err != nil {
			return err
		}
		if !exists {
			return notFound("approval_not_found", "approval %d does not exist", approvalID)
		}

		posted, alreadyPosted, err := findJournal(ctx, tx, "approval_id = ?", approval.ID)
		if err != nil {
			return err
		}
		if alreadyPosted {
			posted.Replayed = true
			result = posted
			return nil
		}

		proposal, exists, err := getProposal(ctx, tx, approval.ProposalID)
		if err != nil {
			return err
		}
		if !exists {
			return fmt.Errorf("approval %d refers to missing proposal %d", approval.ID, approval.ProposalID)
		}
		if proposal.Fingerprint != approval.ProposalFingerprint || proposalFingerprint(proposal.input()) != proposal.Fingerprint {
			return refuse(rejected("proposal_changed", "proposal %d no longer matches what reviewer %s approved", proposal.ID, approval.Reviewer))
		}
		if proposal.Status != ProposalOpen {
			return refuse(rejected("approval_stale", "approval %d is for proposal %d, which is %s", approval.ID, proposal.ID, proposal.Status))
		}
		facts, failed, err := currentFacts(ctx, tx, proposal)
		if err != nil {
			return err
		}
		if failed != nil {
			return refuse(failed)
		}

		pay := facts.payments[0]
		journal := Journal{
			TenantID:   pay.tenantID,
			PaymentID:  pay.id,
			InvoiceID:  facts.invoice.InvoiceID,
			ProposalID: proposal.ID,
			ApprovalID: approval.ID,
			Currency:   pay.currency,
			Memo:       fmt.Sprintf("%s payment %s settles invoice %s", pay.provider, pay.transactionID, facts.invoice.InvoiceID),
			PostedAt:   now,
			Lines: []JournalLine{
				{Account: AccountBank, DebitMinor: pay.amountMinor},
				{Account: AccountAccountsReceivable, CreditMinor: pay.amountMinor},
			},
		}
		if err := ensureBalanced(journal.Lines); err != nil {
			return err
		}
		journal.ID, err = insertJournal(ctx, tx, journal)
		if err != nil {
			return err
		}
		if err := settleInvoice(ctx, tx, journal.TenantID, journal.InvoiceID); err != nil {
			return err
		}
		if err := moveProposal(ctx, tx, proposal.ID, ProposalOpen, ProposalPosted); err != nil {
			return err
		}
		result = journal
		return insertAudit(ctx, tx, "posted", systemActor, subject, map[string]int64{"journal_id": journal.ID}, now)
	})
	if err != nil {
		return Journal{}, err
	}
	if s.afterPostCommit != nil && !result.Replayed {
		if err := s.afterPostCommit(); err != nil {
			return Journal{}, err
		}
	}
	return result, nil
}

// currentFacts loads the facts for an existing proposal and runs its checks
// again. It returns a rejection, not an error, when a check no longer passes:
// for example, another payment settled the invoice in the meantime.
func currentFacts(ctx context.Context, tx *sql.Tx, p Proposal) (matchFacts, *Error, error) {
	facts, err := loadFacts(ctx, tx, p.input())
	if err != nil {
		return matchFacts{}, nil, err
	}
	if checks := evaluateChecks(facts); !allPassed(checks) {
		return matchFacts{}, &Error{
			Kind:   KindRejected,
			Reason: "checks_failed",
			Detail: fmt.Sprintf("proposal %d no longer passes its checks", p.ID),
			Checks: failedChecks(checks),
		}, nil
	}
	return facts, nil, nil
}

func loadFacts(ctx context.Context, tx *sql.Tx, p ProposalInput) (matchFacts, error) {
	facts := matchFacts{proposal: p}
	var err error
	if facts.payments, err = paymentsByTransaction(ctx, tx, p.TenantID, p.TransactionID); err != nil {
		return matchFacts{}, err
	}
	if len(facts.payments) == 1 {
		if facts.posted, err = paymentHasJournal(ctx, tx, facts.payments[0].id); err != nil {
			return matchFacts{}, err
		}
	}
	if facts.invoice, err = findInvoice(ctx, tx, p.TenantID, p.InvoiceID); err != nil {
		return matchFacts{}, err
	}
	return facts, nil
}

func (p Proposal) input() ProposalInput {
	return ProposalInput{TenantID: p.TenantID, TransactionID: p.TransactionID, InvoiceID: p.InvoiceID, Confidence: p.Confidence}
}

// ensureBalanced is the double-entry invariant, checked before the lines are
// written rather than trusted to the code that built them.
func ensureBalanced(lines []JournalLine) error {
	var debits, credits int64
	for _, line := range lines {
		debits += line.DebitMinor
		credits += line.CreditMinor
	}
	if len(lines) < 2 || debits != credits || debits <= 0 {
		return fmt.Errorf("unbalanced journal: %d lines, debits %d, credits %d", len(lines), debits, credits)
	}
	return nil
}

// inTx runs fn in one BEGIN IMMEDIATE transaction. It commits when fn
// succeeds, and also when fn returns keepEvidence, so that refusal records
// survive while the error still reaches the caller.
func (s *Service) inTx(ctx context.Context, fn func(tx *sql.Tx) error) error {
	tx, err := s.db.BeginTx(ctx, nil)
	if err != nil {
		return fmt.Errorf("begin transaction: %w", err)
	}
	// Releases the write lock if fn panics or fails. After a commit it is a
	// no-op, and its error is less useful than the one being returned.
	defer tx.Rollback()
	fnErr := fn(tx)
	var keep keepEvidence
	if fnErr != nil && !errors.As(fnErr, &keep) {
		return fnErr
	}
	if err := tx.Commit(); err != nil {
		return fmt.Errorf("commit transaction: %w", err)
	}
	if fnErr != nil {
		return keep.err
	}
	return nil
}

// inReadTx runs fn in a read-only transaction. It sees one consistent
// snapshot and, unlike inTx, does not take the write lock.
func (s *Service) inReadTx(ctx context.Context, fn func(tx *sql.Tx) error) error {
	tx, err := s.db.BeginTx(ctx, &sql.TxOptions{ReadOnly: true})
	if err != nil {
		return fmt.Errorf("begin read transaction: %w", err)
	}
	defer tx.Rollback()
	return fn(tx)
}

func (s *Service) timestamp() string {
	return s.now().UTC().Format(time.RFC3339Nano)
}

func validateInvoice(inv Invoice) error {
	switch {
	case inv.TenantID == "" || inv.InvoiceID == "":
		return invalid("missing_field", "invoice tenant and ID are required")
	case !currencyCode.MatchString(inv.Currency):
		return invalid("invalid_currency", "invoice %s/%s currency %q is not a three-letter ISO code", inv.TenantID, inv.InvoiceID, inv.Currency)
	case inv.AmountMinor <= 0:
		return invalid("invalid_amount", "invoice %s/%s amount must be positive", inv.TenantID, inv.InvoiceID)
	case inv.Status != InvoiceOpen:
		// A settled invoice needs the journal that settled it, so it can only
		// become settled through Post.
		return invalid("invalid_status", "invoice %s/%s must be loaded as open, got %q", inv.TenantID, inv.InvoiceID, inv.Status)
	}
	return nil
}

func describeChanges(before, after BankEvent) string {
	var changes []string
	diff := func(field string, a, b any) {
		if a != b {
			changes = append(changes, fmt.Sprintf("%s %v -> %v", field, a, b))
		}
	}
	diff("transaction_id", before.TransactionID, after.TransactionID)
	diff("currency", before.Currency, after.Currency)
	diff("amount_minor", before.AmountMinor, after.AmountMinor)
	diff("reference", before.Reference, after.Reference)
	return strings.Join(changes, ", ")
}

internal/recon/store.go:
package recon

import (
	"context"
	"database/sql"
	"encoding/json"
	"errors"
	"fmt"
)

// The functions in this file read and write single rows inside a caller's
// transaction. They hold no business rules; service.go decides what to do.

type payment struct {
	id            int64
	tenantID      string
	provider      string
	transactionID string
	currency      string
	amountMinor   int64
	fingerprint   string
}

type storedEvent struct {
	event       BankEvent
	fingerprint string
	paymentID   *int64
	accepted    bool
}

// findEvent uses the first delivery, including a refusal, to reserve event
// identity without treating rejected financial content as an accepted payment.
func findEvent(ctx context.Context, tx *sql.Tx, provider, eventID string) (storedEvent, bool, error) {
	var e storedEvent
	var raw, outcome string
	var paymentID sql.NullInt64
	err := tx.QueryRowContext(ctx, `
		SELECT raw_payload, fingerprint, payment_id, outcome FROM event_deliveries
		WHERE provider = ? AND event_id = ? ORDER BY id LIMIT 1`, provider, eventID).
		Scan(&raw, &e.fingerprint, &paymentID, &outcome)
	if err != nil {
		return e, found(err), ignoreNoRows(err)
	}
	if err := json.Unmarshal([]byte(raw), &e.event); err != nil {
		return storedEvent{}, false, fmt.Errorf("read stored event %s/%s: %w", provider, eventID, err)
	}
	e.paymentID = nullableID(paymentID)
	e.accepted = outcome == string(Accepted) || outcome == string(DuplicateTransaction) || outcome == string(DuplicateEvent)
	if e.accepted && e.paymentID == nil {
		return storedEvent{}, false, fmt.Errorf("accepted event %s/%s has no payment", provider, eventID)
	}
	return e, true, nil
}

// findPayment looks a transaction up by its provider identity alone, so a
// copy of it routed to the wrong tenant is caught instead of posted twice.
// The result may belong to another tenant; callers must not show it to the
// event's tenant.
func findPayment(ctx context.Context, tx *sql.Tx, provider, transactionID string) (payment, bool, error) {
	var p payment
	err := tx.QueryRowContext(ctx, `
		SELECT id, tenant_id, provider, transaction_id, currency, amount_minor, fingerprint
		FROM payments WHERE provider = ? AND transaction_id = ?`,
		provider, transactionID).
		Scan(&p.id, &p.tenantID, &p.provider, &p.transactionID, &p.currency, &p.amountMinor, &p.fingerprint)
	return p, found(err), ignoreNoRows(err)
}

// paymentsByTransaction finds payments by the fields a proposal carries. The
// tenant filter is what makes a cross-tenant match impossible to load.
func paymentsByTransaction(ctx context.Context, tx *sql.Tx, tenantID, transactionID string) ([]payment, error) {
	rows, err := tx.QueryContext(ctx, `
		SELECT id, tenant_id, provider, transaction_id, currency, amount_minor, fingerprint
		FROM payments WHERE tenant_id = ? AND transaction_id = ? ORDER BY id`, tenantID, transactionID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var payments []payment
	for rows.Next() {
		var p payment
		if err := rows.Scan(&p.id, &p.tenantID, &p.provider, &p.transactionID, &p.currency, &p.amountMinor, &p.fingerprint); err != nil {
			return nil, err
		}
		payments = append(payments, p)
	}
	return payments, rows.Err()
}

func insertPayment(ctx context.Context, tx *sql.Tx, e BankEvent, fingerprint, now string) (int64, error) {
	res, err := tx.ExecContext(ctx, `
		INSERT INTO payments (tenant_id, provider, transaction_id, currency, amount_minor, fingerprint, created_at)
		VALUES (?, ?, ?, ?, ?, ?, ?)`,
		e.TenantID, e.Provider, e.TransactionID, e.Currency, e.AmountMinor, fingerprint, now)
	if err != nil {
		return 0, err
	}
	return res.LastInsertId()
}

func insertEvent(ctx context.Context, tx *sql.Tx, e BankEvent, fingerprint string, raw []byte, paymentID int64, now string) error {
	_, err := tx.ExecContext(ctx, `
		INSERT INTO bank_events (provider, event_id, tenant_id, transaction_id, currency, amount_minor,
			reference, fingerprint, raw_payload, payment_id, received_at)
		VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
		e.Provider, e.EventID, e.TenantID, e.TransactionID, e.Currency, e.AmountMinor,
		e.Reference, fingerprint, string(raw), paymentID, now)
	return err
}

func insertDelivery(ctx context.Context, tx *sql.Tx, e BankEvent, outcome, fingerprint string, raw []byte, paymentID *int64, now string) error {
	_, err := tx.ExecContext(ctx, `
		INSERT INTO event_deliveries (provider, event_id, outcome, fingerprint, raw_payload, payment_id, received_at)
		VALUES (?, ?, ?, ?, ?, ?, ?)`,
		e.Provider, e.EventID, outcome, fingerprint, string(raw), paymentID, now)
	return err
}

func findInvoice(ctx context.Context, tx *sql.Tx, tenantID, invoiceID string) (*Invoice, error) {
	var inv Invoice
	err := tx.QueryRowContext(ctx, `
		SELECT tenant_id, invoice_id, currency, amount_minor, status
		FROM invoices WHERE tenant_id = ? AND invoice_id = ?`, tenantID, invoiceID).
		Scan(&inv.TenantID, &inv.InvoiceID, &inv.Currency, &inv.AmountMinor, &inv.Status)
	if errors.Is(err, sql.ErrNoRows) {
		return nil, nil
	}
	if err != nil {
		return nil, err
	}
	return &inv, nil
}

func paymentHasJournal(ctx context.Context, tx *sql.Tx, paymentID int64) (bool, error) {
	var exists bool
	err := tx.QueryRowContext(ctx, `SELECT EXISTS (SELECT 1 FROM journal_entries WHERE payment_id = ?)`, paymentID).Scan(&exists)
	return exists, err
}

const proposalColumns = `id, tenant_id, transaction_id, invoice_id, confidence, fingerprint,
	payment_id, checks, status, supersedes, created_at`

type rowScanner interface{ Scan(dest ...any) error }

func scanProposal(row rowScanner) (Proposal, error) {
	var p Proposal
	var checks string
	var paymentID, supersedes sql.NullInt64
	err := row.Scan(&p.ID, &p.TenantID, &p.TransactionID, &p.InvoiceID, &p.Confidence, &p.Fingerprint,
		&paymentID, &checks, &p.Status, &supersedes, &p.CreatedAt)
	if err != nil {
		return Proposal{}, err
	}
	if err := json.Unmarshal([]byte(checks), &p.Checks); err != nil {
		return Proposal{}, fmt.Errorf("proposal %d checks: %w", p.ID, err)
	}
	p.PaymentID = nullableID(paymentID)
	p.Supersedes = nullableID(supersedes)
	return p, nil
}

func getProposal(ctx context.Context, tx *sql.Tx, id int64) (Proposal, bool, error) {
	p, err := scanProposal(tx.QueryRowContext(ctx, `SELECT `+proposalColumns+` FROM proposals WHERE id = ?`, id))
	return p, found(err), ignoreNoRows(err)
}

// liveProposalByFingerprint finds an identical proposal that still stands.
// Rejected and superseded proposals are history, so resubmitting the same
// content re-evaluates it instead of returning the old verdict.
func liveProposalByFingerprint(ctx context.Context, tx *sql.Tx, fingerprint string) (Proposal, bool, error) {
	p, err := scanProposal(tx.QueryRowContext(ctx, `
		SELECT `+proposalColumns+` FROM proposals
		WHERE fingerprint = ? AND status IN ('open', 'posted')
		ORDER BY id DESC LIMIT 1`, fingerprint))
	return p, found(err), ignoreNoRows(err)
}

func openProposalForPayment(ctx context.Context, tx *sql.Tx, paymentID int64) (Proposal, bool, error) {
	p, err := scanProposal(tx.QueryRowContext(ctx, `
		SELECT `+proposalColumns+` FROM proposals WHERE payment_id = ? AND status = 'open'`, paymentID))
	return p, found(err), ignoreNoRows(err)
}

func insertProposal(ctx context.Context, tx *sql.Tx, p Proposal) (int64, error) {
	checks, err := json.Marshal(p.Checks)
	if err != nil {
		return 0, err
	}
	res, err := tx.ExecContext(ctx, `
		INSERT INTO proposals (tenant_id, transaction_id, invoice_id, confidence, fingerprint,
			payment_id, checks, status, supersedes, created_at)
		VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
		p.TenantID, p.TransactionID, p.InvoiceID, p.Confidence, p.Fingerprint,
		p.PaymentID, string(checks), p.Status, p.Supersedes, p.CreatedAt)
	if err != nil {
		return 0, err
	}
	return res.LastInsertId()
}

// moveProposal changes status only if the proposal is still in the expected
// state, so a concurrent change is detected instead of overwritten.
func moveProposal(ctx context.Context, tx *sql.Tx, id int64, from, to string) error {
	res, err := tx.ExecContext(ctx, `UPDATE proposals SET status = ? WHERE id = ? AND status = ?`, to, id, from)
	if err != nil {
		return err
	}
	return expectOneRow(res, "proposal %d %s -> %s", id, from, to)
}

func findApproval(ctx context.Context, tx *sql.Tx, query string, arg int64) (Approval, bool, error) {
	var a Approval
	err := tx.QueryRowContext(ctx, `
		SELECT id, proposal_id, proposal_fingerprint, reviewer, approved_at
		FROM approvals WHERE `+query, arg).
		Scan(&a.ID, &a.ProposalID, &a.ProposalFingerprint, &a.Reviewer, &a.ApprovedAt)
	return a, found(err), ignoreNoRows(err)
}

func getApproval(ctx context.Context, tx *sql.Tx, id int64) (Approval, bool, error) {
	return findApproval(ctx, tx, "id = ?", id)
}

func approvalForProposal(ctx context.Context, tx *sql.Tx, proposalID int64) (Approval, bool, error) {
	return findApproval(ctx, tx, "proposal_id = ?", proposalID)
}

func insertApproval(ctx context.Context, tx *sql.Tx, a Approval) (int64, error) {
	res, err := tx.ExecContext(ctx, `
		INSERT INTO approvals (proposal_id, proposal_fingerprint, reviewer, approved_at) VALUES (?, ?, ?, ?)`,
		a.ProposalID, a.ProposalFingerprint, a.Reviewer, a.ApprovedAt)
	if err != nil {
		return 0, err
	}
	return res.LastInsertId()
}

type querier interface {
	QueryRowContext(ctx context.Context, query string, args ...any) *sql.Row
	QueryContext(ctx context.Context, query string, args ...any) (*sql.Rows, error)
}

const journalColumns = `id, tenant_id, payment_id, invoice_id, proposal_id, approval_id, currency, memo, posted_at`

func findJournal(ctx context.Context, q querier, where string, arg int64) (Journal, bool, error) {
	var j Journal
	err := q.QueryRowContext(ctx, `SELECT `+journalColumns+` FROM journal_entries WHERE `+where, arg).
		Scan(&j.ID, &j.TenantID, &j.PaymentID, &j.InvoiceID, &j.ProposalID, &j.ApprovalID, &j.Currency, &j.Memo, &j.PostedAt)
	if err != nil {
		return Journal{}, found(err), ignoreNoRows(err)
	}
	j.Lines, err = journalLines(ctx, q, j.ID)
	return j, true, err
}

func journalLines(ctx context.Context, q querier, entryID int64) ([]JournalLine, error) {
	rows, err := q.QueryContext(ctx, `
		SELECT account, debit_minor, credit_minor FROM journal_lines WHERE entry_id = ? ORDER BY id`, entryID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var lines []JournalLine
	for rows.Next() {
		var line JournalLine
		if err := rows.Scan(&line.Account, &line.DebitMinor, &line.CreditMinor); err != nil {
			return nil, err
		}
		lines = append(lines, line)
	}
	return lines, rows.Err()
}

func insertJournal(ctx context.Context, tx *sql.Tx, j Journal) (int64, error) {
	res, err := tx.ExecContext(ctx, `
		INSERT INTO journal_entries (tenant_id, payment_id, invoice_id, proposal_id, approval_id, currency, memo, posted_at)
		VALUES (?, ?, ?, ?, ?, ?, ?, ?)`,
		j.TenantID, j.PaymentID, j.InvoiceID, j.ProposalID, j.ApprovalID, j.Currency, j.Memo, j.PostedAt)
	if err != nil {
		return 0, err
	}
	entryID, err := res.LastInsertId()
	if err != nil {
		return 0, err
	}
	for _, line := range j.Lines {
		if _, err := tx.ExecContext(ctx, `
			INSERT INTO journal_lines (entry_id, account, debit_minor, credit_minor) VALUES (?, ?, ?, ?)`,
			entryID, line.Account, line.DebitMinor, line.CreditMinor); err != nil {
			return 0, err
		}
	}
	return entryID, nil
}

func settleInvoice(ctx context.Context, tx *sql.Tx, tenantID, invoiceID string) error {
	res, err := tx.ExecContext(ctx, `
		UPDATE invoices SET status = 'settled' WHERE tenant_id = ? AND invoice_id = ? AND status = 'open'`,
		tenantID, invoiceID)
	if err != nil {
		return err
	}
	return expectOneRow(res, "settle invoice %s/%s", tenantID, invoiceID)
}

func insertAudit(ctx context.Context, tx *sql.Tx, action, actor, subject string, detail any, now string) error {
	encoded, err := json.Marshal(detail)
	if err != nil {
		return err
	}
	_, err = tx.ExecContext(ctx, `
		INSERT INTO audit_events (action, actor, subject, detail, occurred_at) VALUES (?, ?, ?, ?, ?)`,
		action, actor, subject, string(encoded), now)
	return err
}

func expectOneRow(res sql.Result, format string, args ...any) error {
	n, err := res.RowsAffected()
	if err != nil {
		return err
	}
	if n != 1 {
		return fmt.Errorf("%s: expected 1 row, changed %d", fmt.Sprintf(format, args...), n)
	}
	return nil
}

func found(err error) bool { return err == nil }

func ignoreNoRows(err error) error {
	if errors.Is(err, sql.ErrNoRows) {
		return nil
	}
	return err
}

func nullableID(v sql.NullInt64) *int64 {
	if !v.Valid {
		return nil
	}
	return &v.Int64
}

internal/recon/trace.go:
package recon

import (
	"context"
	"database/sql"
	"encoding/json"
	"fmt"
	"strings"
)

// Delivery is one stored delivery attempt.
type Delivery struct {
	ID          int64           `json:"id"`
	Provider    string          `json:"provider"`
	EventID     string          `json:"event_id"`
	Outcome     string          `json:"outcome"`
	Fingerprint string          `json:"fingerprint"`
	Payload     json.RawMessage `json:"payload"`
	ReceivedAt  string          `json:"received_at"`
}

// AuditEvent is a stored decision.
type AuditEvent struct {
	Action     string          `json:"action"`
	Actor      string          `json:"actor"`
	Subject    string          `json:"subject"`
	Detail     json.RawMessage `json:"detail"`
	OccurredAt string          `json:"occurred_at"`
}

// PaymentTrace is everything recorded about one payment, in the order it
// happened.
type PaymentTrace struct {
	PaymentID     int64        `json:"payment_id"`
	Provider      string       `json:"provider"`
	TransactionID string       `json:"transaction_id"`
	Currency      string       `json:"currency"`
	AmountMinor   int64        `json:"amount_minor"`
	Deliveries    []Delivery   `json:"deliveries"`
	Proposals     []Proposal   `json:"proposals"`
	Approvals     []Approval   `json:"approvals"`
	Journal       *Journal     `json:"journal"`
	Audit         []AuditEvent `json:"audit"`
}

// Trace is the evidence for one tenant's transaction ID.
type Trace struct {
	TenantID      string         `json:"tenant_id"`
	TransactionID string         `json:"transaction_id"`
	Payments      []PaymentTrace `json:"payments"`
	// Unresolved holds rejected proposals that named this transaction but
	// matched no payment in the tenant, for example a cross-tenant guess.
	Unresolved []Proposal `json:"unresolved_proposals"`
}

// Trace returns everything recorded for tenantID's transaction. Every lookup
// is scoped to that tenant. It reads one consistent snapshot without taking
// the write lock.
func (s *Service) Trace(ctx context.Context, tenantID, transactionID string) (Trace, error) {
	trace := Trace{TenantID: tenantID, TransactionID: transactionID, Payments: []PaymentTrace{}, Unresolved: []Proposal{}}
	err := s.inReadTx(ctx, func(tx *sql.Tx) error {
		payments, err := paymentsByTransaction(ctx, tx, tenantID, transactionID)
		if err != nil {
			return err
		}
		for _, pay := range payments {
			paymentTrace, err := tracePayment(ctx, tx, pay)
			if err != nil {
				return err
			}
			trace.Payments = append(trace.Payments, paymentTrace)
		}
		trace.Unresolved, err = queryProposals(ctx, tx, `
			WHERE payment_id IS NULL AND tenant_id = ? AND transaction_id = ? ORDER BY id`, tenantID, transactionID)
		if err != nil {
			return err
		}
		if len(trace.Payments) == 0 && len(trace.Unresolved) == 0 {
			return notFound("nothing_recorded", "nothing is recorded for transaction %s in tenant %s", transactionID, tenantID)
		}
		return nil
	})
	return trace, err
}

func queryProposals(ctx context.Context, tx *sql.Tx, where string, args ...any) ([]Proposal, error) {
	rows, err := tx.QueryContext(ctx, `SELECT `+proposalColumns+` FROM proposals `+where, args...)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	proposals := []Proposal{}
	for rows.Next() {
		p, err := scanProposal(rows)
		if err != nil {
			return nil, err
		}
		proposals = append(proposals, p)
	}
	return proposals, rows.Err()
}

func tracePayment(ctx context.Context, tx *sql.Tx, pay payment) (PaymentTrace, error) {
	trace := PaymentTrace{
		PaymentID:     pay.id,
		Provider:      pay.provider,
		TransactionID: pay.transactionID,
		Currency:      pay.currency,
		AmountMinor:   pay.amountMinor,
	}

	rows, err := tx.QueryContext(ctx, `
		SELECT id, provider, event_id, outcome, fingerprint, raw_payload, received_at
		FROM event_deliveries WHERE payment_id = ? ORDER BY id`, pay.id)
	if err != nil {
		return trace, err
	}
	for rows.Next() {
		var d Delivery
		var payload string
		if err := rows.Scan(&d.ID, &d.Provider, &d.EventID, &d.Outcome, &d.Fingerprint, &payload, &d.ReceivedAt); err != nil {
			rows.Close()
			return trace, err
		}
		d.Payload = rawJSON(payload)
		trace.Deliveries = append(trace.Deliveries, d)
	}
	rows.Close()
	if err := rows.Err(); err != nil {
		return trace, err
	}

	trace.Proposals, err = queryProposals(ctx, tx, `WHERE payment_id = ? ORDER BY id`, pay.id)
	if err != nil {
		return trace, err
	}

	subjects := []any{fmt.Sprintf("payment:%d", pay.id)}
	for _, p := range trace.Proposals {
		subjects = append(subjects, fmt.Sprintf("proposal:%d", p.ID))
		approval, approved, err := approvalForProposal(ctx, tx, p.ID)
		if err != nil {
			return trace, err
		}
		if approved {
			trace.Approvals = append(trace.Approvals, approval)
			subjects = append(subjects, fmt.Sprintf("approval:%d", approval.ID))
		}
	}

	journal, posted, err := findJournal(ctx, tx, "payment_id = ?", pay.id)
	if err != nil {
		return trace, err
	}
	if posted {
		trace.Journal = &journal
	}

	rows, err = tx.QueryContext(ctx, `
		SELECT action, actor, subject, detail, occurred_at FROM audit_events
		WHERE subject IN (?`+strings.Repeat(", ?", len(subjects)-1)+`) ORDER BY id`, subjects...)
	if err != nil {
		return trace, err
	}
	defer rows.Close()
	for rows.Next() {
		var a AuditEvent
		var detail string
		if err := rows.Scan(&a.Action, &a.Actor, &a.Subject, &detail, &a.OccurredAt); err != nil {
			return trace, err
		}
		a.Detail = rawJSON(detail)
		trace.Audit = append(trace.Audit, a)
	}
	return trace, rows.Err()
}

// rawJSON keeps stored JSON as JSON in the trace. A payload that is not
// valid JSON is still shown, as a string, rather than hidden.
func rawJSON(stored string) json.RawMessage {
	if json.Valid([]byte(stored)) {
		return json.RawMessage(stored)
	}
	quoted, _ := json.Marshal(stored)
	return quoted
}

// LedgerReport summarises the whole ledger. Problems is empty when every
// invariant holds.
type LedgerReport struct {
	Journals        int      `json:"journals"`
	Lines           int      `json:"lines"`
	SettledInvoices int      `json:"settled_invoices"`
	Problems        []string `json:"problems"`
}

// VerifyLedger checks the invariants a reviewer cares about across the whole
// database, independently of the code that wrote it.
func (s *Service) VerifyLedger(ctx context.Context) (LedgerReport, error) {
	report := LedgerReport{Problems: []string{}}
	err := s.inReadTx(ctx, func(tx *sql.Tx) error {
		counts := tx.QueryRowContext(ctx, `
			SELECT (SELECT COUNT(*) FROM journal_entries),
			       (SELECT COUNT(*) FROM journal_lines),
			       (SELECT COUNT(*) FROM invoices WHERE status = 'settled')`)
		if err := counts.Scan(&report.Journals, &report.Lines, &report.SettledInvoices); err != nil {
			return err
		}

		invariants := []struct {
			name  string
			query string
		}{
			{"journal is unbalanced or has fewer than two lines", `
				SELECT e.id FROM journal_entries e LEFT JOIN journal_lines l ON l.entry_id = e.id
				GROUP BY e.id
				HAVING COUNT(l.id) < 2 OR COALESCE(SUM(l.debit_minor), 0) <> COALESCE(SUM(l.credit_minor), 0)`},
			{"journal is not one bank debit and one receivables credit", `
				SELECT e.id FROM journal_entries e JOIN journal_lines l ON l.entry_id = e.id
				GROUP BY e.id
				HAVING COUNT(*) <> 2
				    OR SUM(l.account = 'bank' AND l.debit_minor > 0) <> 1
				    OR SUM(l.account = 'accounts_receivable' AND l.credit_minor > 0) <> 1`},
			{"journal amount differs from its payment or invoice", `
				SELECT e.id FROM journal_entries e
				JOIN payments p ON p.id = e.payment_id
				JOIN invoices i ON i.tenant_id = e.tenant_id AND i.invoice_id = e.invoice_id
				JOIN journal_lines l ON l.entry_id = e.id
				GROUP BY e.id HAVING SUM(l.debit_minor) <> MAX(p.amount_minor) OR SUM(l.debit_minor) <> MAX(i.amount_minor)`},
			{"journal currency or tenant differs from its payment or invoice", `
				SELECT e.id FROM journal_entries e
				JOIN payments p ON p.id = e.payment_id
				JOIN invoices i ON i.tenant_id = e.tenant_id AND i.invoice_id = e.invoice_id
				WHERE e.currency <> p.currency OR e.currency <> i.currency OR e.tenant_id <> p.tenant_id`},
			{"journal does not match its approved proposal", `
				SELECT e.id FROM journal_entries e
				JOIN approvals a ON a.id = e.approval_id
				JOIN proposals pr ON pr.id = e.proposal_id
				WHERE a.proposal_id <> pr.id OR a.proposal_fingerprint <> pr.fingerprint OR pr.status <> 'posted'
					   OR pr.payment_id IS NOT e.payment_id OR pr.invoice_id <> e.invoice_id OR pr.tenant_id <> e.tenant_id`},
			{"journal invoice is not settled", `
					SELECT e.id FROM journal_entries e
					JOIN invoices i ON i.tenant_id = e.tenant_id AND i.invoice_id = e.invoice_id
					WHERE i.status <> 'settled'`},
			{"settled invoice has no journal", `
				SELECT i.rowid FROM invoices i
				WHERE i.status = 'settled'
				  AND NOT EXISTS (SELECT 1 FROM journal_entries e WHERE e.tenant_id = i.tenant_id AND e.invoice_id = i.invoice_id)`},
			{"invoice has more than one journal", `
				SELECT MIN(e.id) FROM journal_entries e GROUP BY e.tenant_id, e.invoice_id HAVING COUNT(*) > 1`},
		}
		for _, inv := range invariants {
			ids, err := queryIDs(ctx, tx, inv.query)
			if err != nil {
				return fmt.Errorf("%s: %w", inv.name, err)
			}
			for _, id := range ids {
				report.Problems = append(report.Problems, fmt.Sprintf("%s (id %d)", inv.name, id))
			}
		}
		return nil
	})
	return report, err
}

func queryIDs(ctx context.Context, tx *sql.Tx, query string) ([]int64, error) {
	rows, err := tx.QueryContext(ctx, query)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var ids []int64
	for rows.Next() {
		var id int64
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		ids = append(ids, id)
	}
	return ids, rows.Err()
}

cmd/recon/main.go:
// Command recon is a CLI for the Helix reconciliation service.
//
// Every command prints one JSON document to stdout. The exit code says what
// kind of failure happened, so scripts can branch without parsing text:
//
//	0 success, 1 internal error, 2 invalid input, 3 conflict,
//	4 rejected by a rule, 5 not found, 70 simulated crash
package main

import (
	"context"
	"encoding/csv"
	"encoding/json"
	"errors"
	"flag"
	"fmt"
	"io"
	"os"
	"strconv"
	"strings"

	"github.com/glamboyosa/helix-recon/internal/db"
	"github.com/glamboyosa/helix-recon/internal/recon"
)

const (
	exitOK       = 0
	exitInternal = 1
	exitInvalid  = 2
	exitConflict = 3
	exitRejected = 4
	exitNotFound = 5
	// exitCrashed mimics a process that dies after its posting transaction
	// commits but before it reports success. 70 is EX_SOFTWARE.
	exitCrashed = 70
)

const usage = `usage: recon <command> [flags]

commands:
  load-invoices FILE                         load invoice fixtures (CSV)
  ingest FILE|-                              ingest one bank event (JSON)
  propose FILE|-                             submit a proposed match (JSON)
  approve -proposal ID -fingerprint HASH -reviewer NAME
  post -approval ID [-simulate-crash-after-commit]
  trace -tenant ID -transaction ID           show the evidence for a payment
  verify                                     check ledger invariants

flags go before FILE. Every command accepts -db PATH (default recon.db, or $RECON_DB).`

func main() {
	os.Exit(run(context.Background(), os.Args[1:], os.Stdin, os.Stdout, os.Stderr))
}

func run(ctx context.Context, args []string, stdin io.Reader, stdout, stderr io.Writer) int {
	if len(args) == 0 {
		fmt.Fprintln(stderr, usage)
		return exitInvalid
	}
	command, args := args[0], args[1:]

	flags := flag.NewFlagSet(command, flag.ContinueOnError)
	flags.SetOutput(stderr)
	dbPath := flags.String("db", envOr("RECON_DB", "recon.db"), "SQLite database path")
	proposalID := flags.Int64("proposal", 0, "proposal ID to approve")
	fingerprint := flags.String("fingerprint", "", "fingerprint of the proposal you reviewed")
	reviewer := flags.String("reviewer", "", "reviewer identity (simulated)")
	approvalID := flags.Int64("approval", 0, "approval ID to post")
	crash := flags.Bool("simulate-crash-after-commit", false, "exit after the journal commits, before reporting success")
	tenant := flags.String("tenant", "", "tenant ID")
	transaction := flags.String("transaction", "", "transaction ID")
	if err := flags.Parse(args); err != nil {
		return exitInvalid
	}
	if err := checkFlags(command, flags); err != nil {
		fmt.Fprintln(stderr, err)
		return exitInvalid
	}

	conn, err := db.Open(ctx, *dbPath)
	if err != nil {
		fmt.Fprintln(stderr, err)
		return exitInternal
	}
	defer conn.Close()

	opts := recon.Options{}
	if *crash {
		// Exit without closing anything or printing a result, as a crash would.
		opts.AfterPostCommit = func() error {
			os.Exit(exitCrashed)
			return nil
		}
	}
	service := recon.New(conn, opts)

	var result any
	switch command {
	case "load-invoices":
		var raw []byte
		if raw, err = readInput(flags.Arg(0), stdin); err == nil {
			var invoices []recon.Invoice
			if invoices, err = parseInvoicesCSV(raw); err == nil {
				if err = service.LoadInvoices(ctx, invoices); err == nil {
					result = map[string]int{"loaded": len(invoices)}
				}
			}
		}
	case "ingest":
		var raw []byte
		if raw, err = readInput(flags.Arg(0), stdin); err == nil {
			result, err = onlyOnSuccess(service.Ingest(ctx, raw))
		}
	case "propose":
		var raw []byte
		if raw, err = readInput(flags.Arg(0), stdin); err == nil {
			var proposal recon.Proposal
			proposal, err = service.Propose(ctx, raw)
			// A rejected proposal is still stored; show it with the error.
			if proposal.ID != 0 {
				result = proposal
			}
		}
	case "approve":
		result, err = onlyOnSuccess(service.Approve(ctx, recon.ApprovalRequest{
			ProposalID: *proposalID, Fingerprint: *fingerprint, Reviewer: *reviewer,
		}))
	case "post":
		result, err = onlyOnSuccess(service.Post(ctx, *approvalID))
	case "trace":
		result, err = onlyOnSuccess(service.Trace(ctx, *tenant, *transaction))
	case "verify":
		var ledger recon.LedgerReport
		ledger, err = service.VerifyLedger(ctx)
		result = ledger
		if err == nil && len(ledger.Problems) > 0 {
			err = errors.New("ledger invariants violated")
		}
	}

	return report(stdout, stderr, result, err)
}

// report prints the result and the error, if any, as one JSON object.
func report(stdout, stderr io.Writer, result any, err error) int {
	out := map[string]any{}
	if result != nil {
		out["result"] = result
	}
	code := exitOK
	if err != nil {
		var domainErr *recon.Error
		if errors.As(err, &domainErr) {
			out["error"] = domainErr
			code = exitCodeFor(domainErr.Kind)
		} else {
			out["error"] = map[string]string{"kind": "internal", "detail": err.Error()}
			code = exitInternal
		}
	}
	encoder := json.NewEncoder(stdout)
	encoder.SetIndent("", "  ")
	encoder.SetEscapeHTML(false)
	if encodeErr := encoder.Encode(out); encodeErr != nil {
		fmt.Fprintln(stderr, encodeErr)
		return exitInternal
	}
	return code
}

// commandFlags lists the flags each command reads, so a flag given to the
// wrong command is an error instead of being silently ignored.
var commandFlags = map[string][]string{
	"load-invoices": {"db"},
	"ingest":        {"db"},
	"propose":       {"db"},
	"approve":       {"db", "proposal", "fingerprint", "reviewer"},
	"post":          {"db", "approval", "simulate-crash-after-commit"},
	"trace":         {"db", "tenant", "transaction"},
	"verify":        {"db"},
}

func checkFlags(command string, flags *flag.FlagSet) error {
	allowed, known := commandFlags[command]
	if !known {
		return fmt.Errorf("unknown command %q\n\n%s", command, usage)
	}
	var err error
	flags.Visit(func(f *flag.Flag) {
		for _, name := range allowed {
			if f.Name == name {
				return
			}
		}
		if err == nil {
			err = fmt.Errorf("%s does not take -%s", command, f.Name)
		}
	})
	if err != nil {
		return err
	}
	switch command {
	case "load-invoices", "ingest", "propose":
		if flags.NArg() != 1 {
			return fmt.Errorf("%s requires exactly one input file; put flags before FILE", command)
		}
	default:
		if flags.NArg() != 0 {
			return fmt.Errorf("%s does not take positional arguments", command)
		}
	}
	return nil
}

// onlyOnSuccess drops the zero-value result that accompanies an error, so the
// output does not show an empty record next to the failure.
func onlyOnSuccess[T any](result T, err error) (any, error) {
	if err != nil {
		return nil, err
	}
	return result, nil
}

func exitCodeFor(kind recon.Kind) int {
	switch kind {
	case recon.KindInvalid:
		return exitInvalid
	case recon.KindConflict:
		return exitConflict
	case recon.KindRejected:
		return exitRejected
	case recon.KindNotFound:
		return exitNotFound
	default:
		return exitInternal
	}
}

func readInput(path string, stdin io.Reader) ([]byte, error) {
	switch path {
	case "":
		return nil, errors.New("an input file is required (use - for stdin)")
	case "-":
		return io.ReadAll(stdin)
	default:
		return os.ReadFile(path)
	}
}

// parseInvoicesCSV reads lines like "tenant-a, inv-1, GBP, 12000, open".
// Lines starting with # are comments.
func parseInvoicesCSV(raw []byte) ([]recon.Invoice, error) {
	reader := csv.NewReader(strings.NewReader(string(raw)))
	reader.Comment = '#'
	reader.TrimLeadingSpace = true
	reader.FieldsPerRecord = 5
	records, err := reader.ReadAll()
	if err != nil {
		return nil, fmt.Errorf("invoice fixtures: %w", err)
	}
	invoices := make([]recon.Invoice, 0, len(records))
	for i, record := range records {
		amount, err := strconv.ParseInt(record[3], 10, 64)
		if err != nil {
			return nil, fmt.Errorf("invoice fixtures line %d: amount %q is not an integer number of minor units", i+1, record[3])
		}
		invoices = append(invoices, recon.Invoice{
			TenantID: record[0], InvoiceID: record[1], Currency: record[2], AmountMinor: amount, Status: record[4],
		})
	}
	return invoices, nil
}

func envOr(key, fallback string) string {
	if value := os.Getenv(key); value != "" {
		return value
	}
	return fallback
}

internal/recon/recon_test.go:
package recon_test

import (
	"context"
	"strings"
	"sync"
	"testing"

	"github.com/glamboyosa/helix-recon/internal/recon"
)

func TestHappyPathPostsOneBalancedJournal(t *testing.T) {
	h := newHarness(t, recon.Options{})

	ingested := h.mustIngest(event())
	if ingested.Outcome != recon.Accepted {
		t.Fatalf("outcome = %s, want accepted", ingested.Outcome)
	}

	p := h.mustPropose(proposal())
	if p.Status != recon.ProposalOpen {
		t.Fatalf("proposal status = %s, want open; checks %+v", p.Status, p.Checks)
	}
	for _, check := range p.Checks {
		if !check.Passed {
			t.Fatalf("check %s failed: %s", check.Name, check.Detail)
		}
	}

	a := h.mustApprove(p, "reviewer@tenant-a.test")
	if a.Reviewer != "reviewer@tenant-a.test" || a.ProposalFingerprint != p.Fingerprint {
		t.Fatalf("approval = %+v, want it bound to proposal %d and the reviewer", a, p.ID)
	}

	j := h.mustPost(a)
	if j.Replayed {
		t.Fatal("first post reported as a replay")
	}
	wantLines := []recon.JournalLine{
		{Account: recon.AccountBank, DebitMinor: 12000},
		{Account: recon.AccountAccountsReceivable, CreditMinor: 12000},
	}
	if j.Currency != "GBP" || j.TenantID != "tenant-a" || j.InvoiceID != "inv-1" {
		t.Fatalf("journal = %+v", j)
	}
	if len(j.Lines) != 2 || j.Lines[0] != wantLines[0] || j.Lines[1] != wantLines[1] {
		t.Fatalf("lines = %+v, want %+v", j.Lines, wantLines)
	}
	if got := h.invoiceStatus("tenant-a", "inv-1"); got != recon.InvoiceSettled {
		t.Fatalf("inv-1 = %s, want settled", got)
	}
	if got := h.invoiceStatus("tenant-a", "inv-2"); got != recon.InvoiceOpen {
		t.Fatalf("inv-2 = %s, want open", got)
	}
	if got := h.invoiceStatus("tenant-b", "inv-1"); got != recon.InvoiceOpen {
		t.Fatalf("tenant-b inv-1 = %s, want open", got)
	}
	report := h.requireHealthyLedger()
	if report.Journals != 1 || report.Lines != 2 || report.SettledInvoices != 1 {
		t.Fatalf("report = %+v", report)
	}

	// The trace ties the delivery, proposal, approval and journal together.
	traced, err := h.svc.Trace(context.Background(), "tenant-a", "txn-1")
	if err != nil {
		t.Fatalf("trace: %v", err)
	}
	if len(traced.Payments) != 1 {
		t.Fatalf("traced payments = %d, want 1", len(traced.Payments))
	}
	trace := traced.Payments[0]
	if len(trace.Deliveries) != 1 || len(trace.Proposals) != 1 || len(trace.Approvals) != 1 || trace.Journal == nil {
		t.Fatalf("incomplete trace: %+v", trace)
	}
	if trace.Journal.ApprovalID != a.ID || trace.Approvals[0].ProposalID != p.ID || trace.Proposals[0].Status != recon.ProposalPosted {
		t.Fatalf("trace links do not line up: %+v", trace)
	}
	actions := map[string]bool{}
	for _, event := range trace.Audit {
		actions[event.Action] = true
	}
	if !actions["approved"] || !actions["posted"] {
		t.Fatalf("audit actions = %v, want approved and posted", actions)
	}
}

func TestDuplicateDeliveryCreatesNothingNew(t *testing.T) {
