	if again.Outcome != recon.DuplicateEvent || again.PaymentID != first.PaymentID {
		t.Fatalf("redelivery = %+v, want duplicate of payment %d", again, first.PaymentID)
	}
	// Different key order and whitespace are still the same content.
	reordered := []byte(`{ "reference":"Payment INV-1", "amount_minor":12000, "currency":"GBP",
		"transaction_id":"txn-1", "event_id":"evt-1", "provider":"demo", "tenant_id":"tenant-a" }`)
