	}

	p := h.mustPropose(proposal())
	h.mustPost(h.mustApprove(p, "reviewer@tenant-a.test"))
	after := h.mustIngest(event())
	if after.Outcome != recon.DuplicateEvent {
		t.Fatalf("redelivery after posting = %s", after.Outcome)
	}

