func TestConcurrentPostsOfTheSamePaymentProduceOneJournal(t *testing.T) {
	h := newHarness(t, recon.Options{})
	h.mustIngest(event())
	p := h.mustPropose(proposal())
	a := h.mustApprove(p, "reviewer@tenant-a.test")

	// Two "processes" with separate connection pools, several attempts each,
	// released at the same moment.
	services := []*recon.Service{h.svc, h.secondProcess()}
	const attempts = 8
	start := make(chan struct{})
	results := make([]recon.Journal, attempts)
	errs := make([]error, attempts)
	var wg sync.WaitGroup
	for i := 0; i < attempts; i++ {
		wg.Add(1)
		go func(i int) {
			defer wg.Done()
			<-start
			results[i], errs[i] = services[i%2].Post(context.Background(), a.ID)
		}(i)
	}
	close(start)
	wg.Wait()

	fresh := 0
	for i := range results {
		if errs[i] != nil {
			t.Fatalf("attempt %d: %v", i, errs[i])
		}
		if results[i].ID != results[0].ID {
			t.Fatalf("attempt %d got journal %d, attempt 0 got %d", i, results[i].ID, results[0].ID)
		}
		if !results[i].Replayed {
			fresh++
		}
	}
	if fresh != 1 {
		t.Fatalf("%d attempts posted, want exactly 1 (the rest replay it)", fresh)
	}
	if l := h.ledger(); l.Journals != 1 || l.Lines != 2 || l.Debits != 12000 || l.Credits != 12000 {
		t.Fatalf("ledger = %+v", l)
	}
	h.requireHealthyLedger()
}

