func TestCrashAfterCommitThenReplayLeavesOneJournal(t *testing.T) {
	crashing := recon.Options{AfterPostCommit: func() error { return errSimulatedCrash }}
	h := newHarness(t, crashing)

	h.mustIngest(event())
	p := h.mustPropose(proposal())
	a := h.mustApprove(p, "reviewer@tenant-a.test")

	// The journal commits, then the process dies before the caller hears.
	if _, err := h.svc.Post(context.Background(), a.ID); err != errSimulatedCrash {
		t.Fatalf("post error = %v, want the simulated crash", err)
	}

	// Restart and replay everything the caller had done, as a caller with
	// no memory of the outcome would.
	h.restart(recon.Options{})
	if r := h.mustIngest(event()); r.Outcome != recon.DuplicateEvent {
		t.Fatalf("replayed ingest = %s", r.Outcome)
	}
	replayedProposal := h.mustPropose(proposal())
	if !replayedProposal.Replayed || replayedProposal.ID != p.ID || replayedProposal.Status != recon.ProposalPosted {
		t.Fatalf("replayed proposal = %+v, want proposal %d, posted", replayedProposal, p.ID)
	}
	replayedApproval := h.mustApprove(replayedProposal, "reviewer@tenant-a.test")
	if !replayedApproval.Replayed || replayedApproval.ID != a.ID {
		t.Fatalf("replayed approval = %+v, want approval %d", replayedApproval, a.ID)
	}
	j := h.mustPost(replayedApproval)
	if !j.Replayed {
		t.Fatal("post after restart created a new journal instead of returning the committed one")
	}

	l := h.ledger()
	if l.Journals != 1 || l.Lines != 2 || l.Debits != l.Credits {
		t.Fatalf("ledger = %+v, want exactly one balanced journal", l)
	}
	if got := h.invoiceStatus("tenant-a", "inv-1"); got != recon.InvoiceSettled {
		t.Fatalf("inv-1 = %s, want settled", got)
	}
	h.requireHealthyLedger()
}

