func TestChangedProposalCannotUseAnEarlierApproval(t *testing.T) {
	t.Run("a newer proposal makes the old approval stale", func(t *testing.T) {
		h := newHarness(t, recon.Options{})
		h.mustIngest(event())
		first := h.mustPropose(proposal())
		firstApproval := h.mustApprove(first, "reviewer@tenant-a.test")

		// The model changes its mind before anything is posted.
		second := h.mustPropose(proposal("invoice_id", "inv-2", "confidence", 0.71))
		if second.Supersedes == nil || *second.Supersedes != first.ID {
			t.Fatalf("second proposal supersedes %v, want %d", second.Supersedes, first.ID)
		}
		before := h.ledger()

		_, err := h.svc.Post(context.Background(), firstApproval.ID)
		requireReason(t, err, recon.KindRejected, "approval_stale")
		if after := h.ledger(); after != before {
			t.Fatalf("ledger changed: %+v -> %+v", before, after)
		}
		if got := h.count(`SELECT COUNT(*) FROM audit_events WHERE action = 'posting_refused'`); got != 1 {
			t.Fatalf("refusals audited = %d, want 1", got)
		}

		// The new proposal needs, and gets, its own approval.
		j := h.mustPost(h.mustApprove(second, "reviewer@tenant-a.test"))
		if j.InvoiceID != "inv-2" {
			t.Fatalf("posted to %s, want inv-2", j.InvoiceID)
		}
		if got := h.invoiceStatus("tenant-a", "inv-1"); got != recon.InvoiceOpen {
			t.Fatalf("inv-1 = %s, want open", got)
		}
		h.requireHealthyLedger()
	})

	t.Run("a re-scored proposal needs a fresh approval", func(t *testing.T) {
		h := newHarness(t, recon.Options{})
		h.mustIngest(event())
		first := h.mustPropose(proposal())
		approval := h.mustApprove(first, "reviewer@tenant-a.test")

		// Same match, new confidence: the reviewer has not seen this version.
		rescored := h.mustPropose(proposal("confidence", 0.6))
		if rescored.ID == first.ID || rescored.Fingerprint == first.Fingerprint {
			t.Fatal("a re-scored proposal must be a new proposal")
		}
		before := h.ledger()
		_, err := h.svc.Post(context.Background(), approval.ID)
		requireReason(t, err, recon.KindRejected, "approval_stale")
		if after := h.ledger(); after != before {
			t.Fatalf("ledger changed: %+v -> %+v", before, after)
		}
	})

	t.Run("approving with the wrong fingerprint is refused", func(t *testing.T) {
		h := newHarness(t, recon.Options{})
		h.mustIngest(event())
		reviewed := h.mustPropose(proposal())
		current := h.mustPropose(proposal("invoice_id", "inv-2"))
		before := h.ledger()

		// The reviewer looked at the first proposal but submits the second's ID.
		_, err := h.svc.Approve(context.Background(), recon.ApprovalRequest{
			ProposalID: current.ID, Fingerprint: reviewed.Fingerprint, Reviewer: "reviewer@tenant-a.test",
		})
		requireReason(t, err, recon.KindRejected, "fingerprint_mismatch")
		if got := h.count(`SELECT COUNT(*) FROM approvals`); got != 0 {
			t.Fatalf("approvals = %d, want 0", got)
		}
		if after := h.ledger(); after != before {
			t.Fatalf("ledger changed: %+v -> %+v", before, after)
		}
	})

	t.Run("stored proposal content cannot be edited", func(t *testing.T) {
		h := newHarness(t, recon.Options{})
		h.mustIngest(event())
		p := h.mustPropose(proposal())
		h.mustApprove(p, "reviewer@tenant-a.test")

		_, err := h.db.Exec(`UPDATE proposals SET invoice_id = 'inv-2' WHERE id = ?`, p.ID)
		if err == nil || !strings.Contains(err.Error(), "proposals may only move from open") {
			t.Fatalf("editing an approved proposal's content: %v, want the trigger to block it", err)
		}
	})

	t.Run("an invoice settled after approval blocks posting", func(t *testing.T) {
		h := newHarness(t, recon.Options{})
		// txn-1 is approved for inv-1 but not posted yet.
		h.mustIngest(event())
		waiting := h.mustApprove(h.mustPropose(proposal()), "reviewer@tenant-a.test")

		// Meanwhile txn-2 pays inv-1 and is posted first.
		h.mustIngest(event("event_id", "evt-2", "transaction_id", "txn-2"))
		h.mustPost(h.mustApprove(h.mustPropose(proposal("transaction_id", "txn-2")), "reviewer@tenant-a.test"))
		before := h.ledger()

		_, err := h.svc.Post(context.Background(), waiting.ID)
		requireReason(t, err, recon.KindRejected, "checks_failed")
		if after := h.ledger(); after != before {
			t.Fatalf("ledger changed: %+v -> %+v", before, after)
		}
		h.requireHealthyLedger()
	})
}

