func TestRepeatedProposalAndApprovalAreIdempotent(t *testing.T) {
	h := newHarness(t, recon.Options{})
	h.mustIngest(event())
	p := h.mustPropose(proposal())
	again := h.mustPropose(proposal())
	if !again.Replayed || again.ID != p.ID {
		t.Fatalf("resubmitted proposal = %+v, want proposal %d replayed", again, p.ID)
	}

	a := h.mustApprove(p, "reviewer@tenant-a.test")
	if again := h.mustApprove(p, "reviewer@tenant-a.test"); !again.Replayed || again.ID != a.ID {
		t.Fatalf("repeated approval = %+v, want approval %d replayed", again, a.ID)
	}
	// A second reviewer does not overwrite the first decision, but the
	// attempt is recorded.
	second := h.mustApprove(p, "someone-else@tenant-a.test")
	if !second.Replayed || second.ID != a.ID || second.Reviewer != "reviewer@tenant-a.test" {
		t.Fatalf("second approval = %+v, want the original by reviewer@tenant-a.test", second)
	}
	if got := h.count(`SELECT COUNT(*) FROM approvals`); got != 1 {
		t.Fatalf("approvals = %d, want 1", got)
	}
	if got := h.count(`SELECT COUNT(*) FROM audit_events WHERE action = 'approval_already_given' AND actor = 'someone-else@tenant-a.test'`); got != 1 {
		t.Fatalf("second reviewer's attempt audited %d times, want 1", got)
	}

	// The system identity can never approve.
	for _, name := range []string{"system", "System", " SYSTEM "} {
		_, err := h.svc.Approve(context.Background(), recon.ApprovalRequest{ProposalID: p.ID, Fingerprint: p.Fingerprint, Reviewer: name})
		requireReason(t, err, recon.KindInvalid, "reserved_reviewer")
	}
}

