		"amount as a string":  []byte(`{"tenant_id":"tenant-a","provider":"demo","event_id":"e","transaction_id":"t","currency":"GBP","amount_minor":"12000","reference":"r"}`),
		"fractional amount":   []byte(`{"tenant_id":"tenant-a","provider":"demo","event_id":"e","transaction_id":"t","currency":"GBP","amount_minor":120.5,"reference":"r"}`),
		"negative amount":     mustJSON(t, event("amount_minor", -12000)),
		"lower-case currency": mustJSON(t, event("currency", "gbp")),
		"missing event ID":    []byte(`{"tenant_id":"tenant-a","provider":"demo","transaction_id":"t","currency":"GBP","amount_minor":12000,"reference":"r"}`),
		"unknown field":       mustJSON(t, event("status", "settled")),
		"two objects":         append(mustJSON(t, event()), mustJSON(t, event())...),
		"not JSON":            []byte(`evt-1`),
		"missing reference":   []byte(`{"tenant_id":"tenant-a","provider":"demo","event_id":"e","transaction_id":"t","currency":"GBP","amount_minor":12000}`),
	}
	for name, raw := range events {
		if _, err := h.svc.Ingest(context.Background(), raw); !recon.IsKind(err, recon.KindInvalid) {
			t.Errorf("event %s: error %v, want invalid", name, err)
		}
	}
	proposals := map[string][]byte{
		"confidence above 1":  mustJSON(t, proposal("confidence", 1.5)),
		"confidence missing":  []byte(`{"tenant_id":"tenant-a","transaction_id":"txn-1","invoice_id":"inv-1"}`),
		"confidence a string": []byte(`{"tenant_id":"tenant-a","transaction_id":"txn-1","invoice_id":"inv-1","confidence":"high"}`),
		"empty invoice":       mustJSON(t, proposal("invoice_id", "")),
	}
	for name, raw := range proposals {
		if _, err := h.svc.Propose(context.Background(), raw); !recon.IsKind(err, recon.KindInvalid) {
			t.Errorf("proposal %s: error %v, want invalid", name, err)
		}
	}
	for _, table := range []string{"payments", "bank_events", "event_deliveries", "proposals"} {
		if got := h.count(`SELECT COUNT(*) FROM ` + table); got != 0 {
			t.Errorf("%s has %d rows, want 0", table, got)
		}
	}
}

func TestSameTransactionRoutedToAnotherTenantIsAConflict(t *testing.T) {
	h := newHarness(t, recon.Options{})
	h.postFixture()
	before := h.ledger()

	// The same provider transaction arrives for tenant-b under a new event
	// ID. tenant-b also has an open inv-1 for the same amount, so without the
	// provider-wide check this would post a second time.
	_, err := h.ingest(event("tenant_id", "tenant-b", "event_id", "evt-9"))
	requireReason(t, err, recon.KindConflict, "transaction_content_changed")
	requireNoLeak(t, err, "tenant-a", "12000", "Payment INV-1")

	if after := h.ledger(); after != before {
		t.Fatalf("ledger changed: %+v -> %+v", before, after)
	}
	if got := h.invoiceStatus("tenant-b", "inv-1"); got != recon.InvoiceOpen {
		t.Fatalf("tenant-b inv-1 = %s, want open", got)
	}
	if got := h.count(`SELECT COUNT(*) FROM event_deliveries WHERE outcome = 'transaction_conflict' AND payment_id IS NULL`); got != 1 {
		t.Fatalf("unlinked conflict deliveries = %d, want 1", got)
	}
	requireTraceHasNoForeignPayload(t, h, "tenant-a", "txn-1", "tenant-b")
}

func TestDatabaseRejectsOneTransactionUnderTwoTenants(t *testing.T) {
	h := newHarness(t, recon.Options{})
	h.mustIngest(event())

	// Bypass the service: the constraint must hold even if the code above
	// it gets the lookup wrong.
	_, err := h.db.Exec(`
		INSERT INTO payments (tenant_id, provider, transaction_id, currency, amount_minor, fingerprint, created_at)
		VALUES ('tenant-b', 'demo', 'txn-1', 'GBP', 12000, 'x', 'now')`)
	if err == nil || !strings.Contains(err.Error(), "UNIQUE") {
		t.Fatalf("second payment for demo/txn-1: %v, want a UNIQUE violation", err)
	}
}

func TestEventIDReusedByAnotherTenantRevealsNothing(t *testing.T) {
	h := newHarness(t, recon.Options{})
	h.mustIngest(event())
	before := h.ledger()

	_, err := h.ingest(event("tenant_id", "tenant-b", "transaction_id", "txn-b", "amount_minor", 500, "reference", "tenant-b secret"))
	requireReason(t, err, recon.KindConflict, "event_content_changed")
	requireNoLeak(t, err, "tenant-a", "txn-1", "12000", "Payment INV-1")
	requireTraceHasNoForeignPayload(t, h, "tenant-a", "txn-1", "tenant-b secret")
	if after := h.ledger(); after != before {
		t.Fatalf("ledger changed: %+v -> %+v", before, after)
	}
}

func TestRejectedProposalWithoutAPaymentIsStillTraceable(t *testing.T) {
	h := newHarness(t, recon.Options{})
	h.mustIngest(event())
	rejectedProposal, err := h.propose(proposal("tenant_id", "tenant-b"))
	requireReason(t, err, recon.KindRejected, "checks_failed")

	traced, err := h.svc.Trace(context.Background(), "tenant-b", "txn-1")
	if err != nil {
		t.Fatalf("trace: %v", err)
	}
	if len(traced.Payments) != 0 || len(traced.Unresolved) != 1 || traced.Unresolved[0].ID != rejectedProposal.ID {
		t.Fatalf("trace = %+v, want only the rejected proposal %d", traced, rejectedProposal.ID)
	}
	// tenant-a's trace does not show tenant-b's guess.
	own, err := h.svc.Trace(context.Background(), "tenant-a", "txn-1")
	if err != nil {
		t.Fatalf("trace: %v", err)
	}
	if len(own.Unresolved) != 0 || len(own.Payments[0].Proposals) != 0 {
		t.Fatalf("tenant-a trace = %+v, want no proposals", own)
	}
}

func TestNegativeZeroConfidenceStillPosts(t *testing.T) {
	h := newHarness(t, recon.Options{})
	h.mustIngest(event())
	p, err := h.svc.Propose(context.Background(), []byte(`{"tenant_id":"tenant-a","transaction_id":"txn-1","invoice_id":"inv-1","confidence":-0}`))
	if err != nil {
		t.Fatalf("propose: %v", err)
	}
	h.mustPost(h.mustApprove(p, "reviewer@tenant-a.test"))
	h.requireHealthyLedger()
}

func TestInvoicesCanOnlyBeLoadedOpen(t *testing.T) {
	h := newHarness(t, recon.Options{})
	settled := recon.Invoice{TenantID: "tenant-a", InvoiceID: "inv-9", Currency: "GBP", AmountMinor: 100, Status: "settled"}
	err := h.svc.LoadInvoices(context.Background(), []recon.Invoice{settled})
	requireReason(t, err, recon.KindInvalid, "invalid_status")
	changed := fixtureInvoices[0]
	changed.AmountMinor = 1
	err = h.svc.LoadInvoices(context.Background(), []recon.Invoice{changed})
	requireReason(t, err, recon.KindConflict, "invoice_content_changed")
	h.requireHealthyLedger()
}

// requireNoLeak fails if an error shown to one tenant mentions another
// tenant's data.
func requireNoLeak(t *testing.T, err error, secrets ...string) {
	t.Helper()
	for _, secret := range secrets {
		if strings.Contains(err.Error(), secret) {
			t.Fatalf("error %q reveals %q", err, secret)
		}
	}
}

func requireTraceHasNoForeignPayload(t *testing.T, h *harness, tenantID, transactionID, foreign string) {
	t.Helper()
	traced, err := h.svc.Trace(context.Background(), tenantID, transactionID)
	if err != nil {
		t.Fatalf("trace: %v", err)
	}
	for _, payment := range traced.Payments {
		for _, delivery := range payment.Deliveries {
			if strings.Contains(string(delivery.Payload), foreign) {
				t.Fatalf("%s's trace shows a delivery containing %q: %s", tenantID, foreign, delivery.Payload)
			}
		}
	}
}

func requireFailedCheck(t *testing.T, p recon.Proposal, name string) {
	t.Helper()
	for _, check := range p.Checks {
		if check.Name == name {
			if check.Passed {
				t.Fatalf("check %s passed, want it to fail", name)
			}
			return
		}
	}
	t.Fatalf("check %s not run; checks: %+v", name, p.Checks)
}

internal/recon/helpers_test.go:
package recon_test

import (
	"context"
	"database/sql"
	"encoding/json"
	"errors"
	"path/filepath"
	"sync"
	"testing"
	"time"

	"github.com/glamboyosa/helix-recon/internal/db"
	"github.com/glamboyosa/helix-recon/internal/recon"
)

// fixtureInvoices are the invoices from the exercise brief.
var fixtureInvoices = []recon.Invoice{
	{TenantID: "tenant-a", InvoiceID: "inv-1", Currency: "GBP", AmountMinor: 12000, Status: "open"},
	{TenantID: "tenant-a", InvoiceID: "inv-2", Currency: "GBP", AmountMinor: 12000, Status: "open"},
	{TenantID: "tenant-b", InvoiceID: "inv-1", Currency: "GBP", AmountMinor: 12000, Status: "open"},
}

var errSimulatedCrash = errors.New("simulated crash after commit")

type harness struct {
	t    *testing.T
	path string
	db   *sql.DB
	svc  *recon.Service
}

// newHarness opens a fresh database file and loads the fixture invoices.
func newHarness(t *testing.T, opts recon.Options) *harness {
	t.Helper()
	h := &harness{t: t, path: filepath.Join(t.TempDir(), "recon.db")}
	h.open(opts)
	if err := h.svc.LoadInvoices(context.Background(), fixtureInvoices); err != nil {
		t.Fatalf("load invoices: %v", err)
	}
	return h
}

// open connects to the harness database. Calling it again after close
// simulates a process restart: nothing survives except what was committed.
func (h *harness) open(opts recon.Options) {
	h.t.Helper()
	conn, err := db.Open(context.Background(), h.path)
	if err != nil {
		h.t.Fatalf("open db: %v", err)
	}
	h.t.Cleanup(func() { conn.Close() })
	if opts.Now == nil {
		opts.Now = steppingClock()
	}
	h.db = conn
	h.svc = recon.New(conn, opts)
}

func (h *harness) restart(opts recon.Options) {
	h.t.Helper()
	if err := h.db.Close(); err != nil {
		h.t.Fatalf("close db: %v", err)
	}
	h.open(opts)
}

// secondProcess returns another Service on its own connection pool, standing
// in for a second worker process sharing the database.
func (h *harness) secondProcess() *recon.Service {
	h.t.Helper()
	conn, err := db.Open(context.Background(), h.path)
	if err != nil {
		h.t.Fatalf("open second connection: %v", err)
	}
	h.t.Cleanup(func() { conn.Close() })
	return recon.New(conn, recon.Options{Now: steppingClock()})
}

func (h *harness) ingest(event map[string]any) (recon.IngestResult, error) {
	return h.svc.Ingest(context.Background(), mustJSON(h.t, event))
}

func (h *harness) mustIngest(event map[string]any) recon.IngestResult {
	h.t.Helper()
	result, err := h.ingest(event)
	if err != nil {
		h.t.Fatalf("ingest: %v", err)
	}
	return result
}

func (h *harness) propose(proposal map[string]any) (recon.Proposal, error) {
	return h.svc.Propose(context.Background(), mustJSON(h.t, proposal))
}

func (h *harness) mustPropose(proposal map[string]any) recon.Proposal {
	h.t.Helper()
	p, err := h.propose(proposal)
	if err != nil {
		h.t.Fatalf("propose: %v", err)
	}
	return p
}

func (h *harness) mustApprove(p recon.Proposal, reviewer string) recon.Approval {
	h.t.Helper()
	a, err := h.svc.Approve(context.Background(), recon.ApprovalRequest{
		ProposalID: p.ID, Fingerprint: p.Fingerprint, Reviewer: reviewer,
	})
	if err != nil {
		h.t.Fatalf("approve proposal %d: %v", p.ID, err)
	}
	return a
}

func (h *harness) mustPost(a recon.Approval) recon.Journal {
	h.t.Helper()
	j, err := h.svc.Post(context.Background(), a.ID)
	if err != nil {
		h.t.Fatalf("post approval %d: %v", a.ID, err)
	}
	return j
}

// ledger is everything a rejected attempt must leave untouched.
type ledger struct {
	Journals      int
	Lines         int
	Debits        int64
	Credits       int64
	OpenInvoices  int
	PostedPayment int
}

func (h *harness) ledger() ledger {
	h.t.Helper()
	var l ledger
	err := h.db.QueryRow(`
		SELECT (SELECT COUNT(*) FROM journal_entries),
		       (SELECT COUNT(*) FROM journal_lines),
		       (SELECT COALESCE(SUM(debit_minor), 0) FROM journal_lines),
		       (SELECT COALESCE(SUM(credit_minor), 0) FROM journal_lines),
		       (SELECT COUNT(*) FROM invoices WHERE status = 'open'),
		       (SELECT COUNT(DISTINCT payment_id) FROM journal_entries)`).
		Scan(&l.Journals, &l.Lines, &l.Debits, &l.Credits, &l.OpenInvoices, &l.PostedPayment)
	if err != nil {
		h.t.Fatalf("read ledger: %v", err)
	}
	return l
}

func (h *harness) count(query string, args ...any) int {
	h.t.Helper()
	var n int
	if err := h.db.QueryRow(query, args...).Scan(&n); err != nil {
		h.t.Fatalf("count %q: %v", query, err)
	}
	return n
}

func (h *harness) invoiceStatus(tenantID, invoiceID string) string {
	h.t.Helper()
	var status string
	err := h.db.QueryRow(`SELECT status FROM invoices WHERE tenant_id = ? AND invoice_id = ?`, tenantID, invoiceID).Scan(&status)
	if err != nil {
		h.t.Fatalf("invoice %s/%s: %v", tenantID, invoiceID, err)
	}
	return status
}

// requireHealthyLedger runs the independent invariant checks.
func (h *harness) requireHealthyLedger() recon.LedgerReport {
	h.t.Helper()
	report, err := h.svc.VerifyLedger(context.Background())
	if err != nil {
		h.t.Fatalf("verify ledger: %v", err)
	}
	if len(report.Problems) > 0 {
		h.t.Fatalf("ledger problems: %v", report.Problems)
	}
	return report
}

// postFixture runs the brief's happy path: evt-1 matched to tenant-a inv-1.
func (h *harness) postFixture() (recon.Proposal, recon.Approval, recon.Journal) {
	h.t.Helper()
	h.mustIngest(event())
	p := h.mustPropose(proposal())
	a := h.mustApprove(p, "reviewer@tenant-a.test")
	return p, a, h.mustPost(a)
}

// event returns the brief's bank event, with any fields overridden.
func event(overrides ...any) map[string]any {
	return with(map[string]any{
		"tenant_id":      "tenant-a",
		"provider":       "demo",
		"event_id":       "evt-1",
		"transaction_id": "txn-1",
		"currency":       "GBP",
		"amount_minor":   12000,
		"reference":      "Payment INV-1",
	}, overrides...)
}

// proposal returns the brief's proposed match, with any fields overridden.
func proposal(overrides ...any) map[string]any {
	return with(map[string]any{
		"tenant_id":      "tenant-a",
		"transaction_id": "txn-1",
		"invoice_id":     "inv-1",
		"confidence":     0.99,
	}, overrides...)
}

func with(base map[string]any, pairs ...any) map[string]any {
	for i := 0; i+1 < len(pairs); i += 2 {
		base[pairs[i].(string)] = pairs[i+1]
	}
	return base
}

func mustJSON(t *testing.T, v any) []byte {
	t.Helper()
	raw, err := json.Marshal(v)
	if err != nil {
		t.Fatalf("marshal: %v", err)
	}
	return raw
}

// steppingClock returns a deterministic clock that advances one second per
// call, so stored timestamps are ordered and stable across runs.
func steppingClock() func() time.Time {
	var mu sync.Mutex
	current := time.Date(2026, 10, 1, 9, 0, 0, 0, time.UTC)
	return func() time.Time {
		mu.Lock()
		defer mu.Unlock()
		current = current.Add(time.Second)
		return current
	}
}

func requireReason(t *testing.T, err error, kind recon.Kind, reason string) {
	t.Helper()
	if !recon.IsKind(err, kind) || recon.Reason(err) != reason {
		t.Fatalf("got error %v, want %s/%s", err, kind, reason)
	}
}

cmd/recon/main_test.go:
package main

import (
	"bytes"
	"context"
	"encoding/json"
	"os"
	"os/exec"
	"path/filepath"
	"strconv"
	"strings"
	"sync"
	"testing"
)

// TestMain lets the test binary act as the CLI, so the crash test can kill a
// real process at the worst moment and start a fresh one.
func TestMain(m *testing.M) {
	if args := os.Getenv("RECON_CLI_ARGS"); args != "" {
		var argv []string
		if err := json.Unmarshal([]byte(args), &argv); err != nil {
			panic(err)
		}
		os.Exit(run(context.Background(), argv, os.Stdin, os.Stdout, os.Stderr))
	}
	os.Exit(m.Run())
}

type cli struct {
	t      *testing.T
	dbPath string
}

// run executes one CLI command in a separate process and decodes its output.
func (c cli) run(args ...string) (int, map[string]any) {
	c.t.Helper()
	argv, err := json.Marshal(append([]string{args[0], "-db", c.dbPath}, args[1:]...))
	if err != nil {
		c.t.Fatal(err)
	}
	cmd := exec.Command(os.Args[0], "-test.run=^$")
	cmd.Env = append(os.Environ(), "RECON_CLI_ARGS="+string(argv))
	var stdout, stderr bytes.Buffer
	cmd.Stdout, cmd.Stderr = &stdout, &stderr
	err = cmd.Run()
	code := 0
	if exitErr, ok := err.(*exec.ExitError); ok {
		code = exitErr.ExitCode()
	} else if err != nil {
		c.t.Fatalf("run %v: %v", args, err)
	}
	var out map[string]any
	if stdout.Len() > 0 {
		if err := json.Unmarshal(stdout.Bytes(), &out); err != nil {
			c.t.Fatalf("%v printed invalid JSON: %v\n%s", args, err, stdout.String())
		}
	}
	return code, out
}

func (c cli) mustRun(args ...string) map[string]any {
	c.t.Helper()
	code, out := c.run(args...)
	if code != exitOK {
		c.t.Fatalf("%v exited %d: %v", args, code, out)
	}
	return out["result"].(map[string]any)
}

func fixture(name string) string {
	return filepath.Join("..", "..", "fixtures", name)
}

func TestCLICrashAfterCommitThenReplay(t *testing.T) {
	c := cli{t: t, dbPath: filepath.Join(t.TempDir(), "recon.db")}

	c.mustRun("load-invoices", fixture("invoices.csv"))
	c.mustRun("ingest", fixture("events/evt-1.json"))
	proposal := c.mustRun("propose", fixture("proposals/txn-1-inv-1.json"))
	proposalID := strconv.FormatInt(int64(proposal["id"].(float64)), 10)
	approval := c.mustRun("approve", "-proposal", proposalID,
		"-fingerprint", proposal["fingerprint"].(string), "-reviewer", "reviewer@tenant-a.test")
	approvalID := strconv.FormatInt(int64(approval["id"].(float64)), 10)

	// The process exits after the commit without printing anything.
	code, out := c.run("post", "-approval", approvalID, "-simulate-crash-after-commit")
	if code != exitCrashed || out != nil {
		t.Fatalf("crashing post exited %d with %v, want %d and no output", code, out, exitCrashed)
	}

	// A new process replays the whole sequence.
	if got := c.mustRun("ingest", fixture("events/evt-1-redelivered-reordered.json")); got["outcome"] != "duplicate_event" {
		t.Fatalf("replayed ingest = %v", got)
	}
	if got := c.mustRun("propose", fixture("proposals/txn-1-inv-1.json")); got["replayed"] != true || got["status"] != "posted" {
		t.Fatalf("replayed proposal = %v", got)
	}
	journal := c.mustRun("post", "-approval", approvalID)
	if journal["replayed"] != true {
		t.Fatalf("post after restart = %v, want the committed journal replayed", journal)
	}

	ledger := c.mustRun("verify")
	if ledger["journals"].(float64) != 1 || len(ledger["problems"].([]any)) != 0 {
		t.Fatalf("ledger = %v, want one journal and no problems", ledger)
	}
}

func TestCLIConcurrentPostsFromSeparateProcesses(t *testing.T) {
	c := cli{t: t, dbPath: filepath.Join(t.TempDir(), "recon.db")}
	c.mustRun("load-invoices", fixture("invoices.csv"))
	c.mustRun("ingest", fixture("events/evt-1.json"))
	proposal := c.mustRun("propose", fixture("proposals/txn-1-inv-1.json"))
	approval := c.mustRun("approve", "-proposal", strconv.FormatInt(int64(proposal["id"].(float64)), 10),
		"-fingerprint", proposal["fingerprint"].(string), "-reviewer", "reviewer@tenant-a.test")
	approvalID := strconv.FormatInt(int64(approval["id"].(float64)), 10)

	const processes = 4
	codes := make([]int, processes)
	outputs := make([]map[string]any, processes)
	var wg sync.WaitGroup
	for i := 0; i < processes; i++ {
		wg.Add(1)
		go func(i int) {
			defer wg.Done()
			codes[i], outputs[i] = c.run("post", "-approval", approvalID)
		}(i)
	}
	wg.Wait()

	fresh := 0
	for i := range codes {
		if codes[i] != exitOK {
			t.Fatalf("process %d exited %d: %v", i, codes[i], outputs[i])
		}
		if outputs[i]["result"].(map[string]any)["replayed"] == false {
			fresh++
		}
	}
	if fresh != 1 {
		t.Fatalf("%d processes posted, want exactly 1", fresh)
	}
	if ledger := c.mustRun("verify"); ledger["journals"].(float64) != 1 {
		t.Fatalf("ledger = %v, want one journal", ledger)
	}
}

func TestCLIExitCodesAndConflictOutput(t *testing.T) {
	c := cli{t: t, dbPath: filepath.Join(t.TempDir(), "recon.db")}
	c.mustRun("load-invoices", fixture("invoices.csv"))
	c.mustRun("ingest", fixture("events/evt-1.json"))

	code, out := c.run("ingest", fixture("events/evt-1-changed-amount.json"))
	if code != exitConflict {
		t.Fatalf("changed event exited %d, want %d: %v", code, exitConflict, out)
	}
	if reason := out["error"].(map[string]any)["reason"]; reason != "event_content_changed" {
		t.Fatalf("reason = %v", reason)
	}

	code, out = c.run("propose", fixture("proposals/cross-tenant.json"))
	if code != exitRejected {
		t.Fatalf("cross-tenant proposal exited %d, want %d: %v", code, exitRejected, out)
	}
	// The rejected proposal is shown alongside the error.
	if out["result"].(map[string]any)["status"] != "rejected" {
		t.Fatalf("output = %v, want the stored rejected proposal", out)
	}

	if code, _ := c.run("post", "-approval", "99"); code != exitNotFound {
		t.Fatalf("unknown approval exited %d, want %d", code, exitNotFound)
	}
	// A flag meant for another command is refused, not ignored.
	if code, _ := c.run("ingest", "-reviewer", "someone", fixture("events/evt-1.json")); code != exitInvalid {
		t.Fatalf("ingest with -reviewer exited %d, want %d", code, exitInvalid)
	}
}

func TestCLIRejectsUnexpectedArgumentsBeforeOpeningDatabase(t *testing.T) {
	for _, args := range [][]string{
		{"ingest"},
		{"ingest", fixture("events/evt-1.json"), "-reviewer", "someone"},
		{"load-invoices", fixture("invoices.csv"), "extra.csv"},
		{"propose"},
		{"approve", "-proposal", "1", "-fingerprint", "x", "-reviewer", "test", "extra"},
		{"post", "-approval", "1", "extra"},
		{"trace", "-tenant", "tenant-a", "-transaction", "txn-1", "extra"},
		{"verify", "extra"},
	} {
		t.Run(strings.Join(args, " "), func(t *testing.T) {
			dbPath := filepath.Join(t.TempDir(), "unused.db")
			argv := append([]string{args[0], "-db", dbPath}, args[1:]...)
			var stdout, stderr bytes.Buffer
			if got := run(context.Background(), argv, strings.NewReader(""), &stdout, &stderr); got != exitInvalid {
				t.Fatalf("exit code = %d, want %d; stdout=%s stderr=%s", got, exitInvalid, &stdout, &stderr)
			}
			if _, err := os.Stat(dbPath); !os.IsNotExist(err) {
				t.Fatalf("invalid arguments created a database: %v", err)
			}
		})
	}
}

