package recon_test

import (
	"context"
	"strings"
	"testing"

	"github.com/glamboyosa/helix-recon/internal/recon"
)

func TestConflictingDeliveryReservesItsEventIdentity(t *testing.T) {
	h := newHarness(t, recon.Options{})
	h.postFixture()
	before := h.ledger()
	conflicting := event("event_id", "evt-2", "amount_minor", 123)
	_, err := h.ingest(conflicting)
	requireReason(t, err, recon.KindConflict, "transaction_content_changed")
	_, err = h.ingest(conflicting)
	requireReason(t, err, recon.KindConflict, "transaction_content_changed")
	h.restart(recon.Options{})

	_, err = h.ingest(event("event_id", "evt-2", "transaction_id", "txn-2"))
	requireReason(t, err, recon.KindConflict, "event_content_changed")
	_, err = h.ingest(event("event_id", "evt-2", "tenant_id", "tenant-b", "transaction_id", "txn-2"))
	requireReason(t, err, recon.KindConflict, "event_content_changed")
	requireNoLeak(t, err, "tenant-a", "123", "Payment INV-1")
	if got := h.count(`SELECT COUNT(*) FROM payments`); got != 1 {
		t.Fatalf("payments = %d, want 1", got)
	}
	if got := h.count(`SELECT COUNT(*) FROM bank_events`); got != 1 {
		t.Fatalf("accepted events = %d, want 1", got)
	}
	if got := h.count(`SELECT COUNT(*) FROM event_deliveries WHERE event_id = 'evt-2'`); got != 4 {
		t.Fatalf("conflict deliveries = %d, want 4", got)
	}
	if after := h.ledger(); after != before {
		t.Fatalf("ledger changed: %+v -> %+v", before, after)
	}
}

func TestRepeatedApprovalRejectsStaleDecisions(t *testing.T) {
	for _, change := range []string{"superseded", "invoice settled"} {
		t.Run(change, func(t *testing.T) {
			h := newHarness(t, recon.Options{})
			h.mustIngest(event())
			p := h.mustPropose(proposal())
			h.mustApprove(p, "reviewer@tenant-a.test")
			wantReason := "proposal_not_open"
			if change == "superseded" {
				h.mustPropose(proposal("invoice_id", "inv-2"))
			} else {
				h.mustIngest(event("event_id", "evt-2", "transaction_id", "txn-2"))
				h.mustPost(h.mustApprove(h.mustPropose(proposal("transaction_id", "txn-2")), "reviewer@tenant-a.test"))
				wantReason = "checks_failed"
			}
			before := h.ledger()
			_, err := h.svc.Approve(context.Background(), recon.ApprovalRequest{
				ProposalID: p.ID, Fingerprint: p.Fingerprint, Reviewer: "reviewer@tenant-a.test",
			})
			requireReason(t, err, recon.KindRejected, wantReason)
			if after := h.ledger(); after != before {
				t.Fatalf("ledger changed: %+v -> %+v", before, after)
			}
			if got := h.count(`SELECT COUNT(*) FROM audit_events WHERE action = 'approval_refused'`); got != 1 {
				t.Fatalf("approval refusals = %d, want 1", got)
			}
		})
	}
}

func TestVerifyLedgerDetectsBrokenPostingLinks(t *testing.T) {
	cases := []struct {
		name         string
		invoiceID    string
		otherPayment bool
		settle       bool
		problem      string
	}{
		{"wrong invoice", "inv-2", false, true, "journal does not match its approved proposal"},
		{"wrong payment", "inv-1", true, true, "journal does not match its approved proposal"},
		{"unsettled invoice", "inv-1", false, false, "journal invoice is not settled"},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			h := newHarness(t, recon.Options{})
			payment := h.mustIngest(event())
			p := h.mustPropose(proposal())
			a := h.mustApprove(p, "reviewer@tenant-a.test")
			if tc.otherPayment {
				payment = h.mustIngest(event("event_id", "evt-2", "transaction_id", "txn-2"))
			}
			// Seed a broken posting directly: verify must not trust Service.Post.
			result, err := h.db.Exec(`
				INSERT INTO journal_entries (tenant_id, payment_id, invoice_id, proposal_id, approval_id, currency, memo, posted_at)
				VALUES ('tenant-a', ?, ?, ?, ?, 'GBP', 'test posting', 'now')`, payment.PaymentID, tc.invoiceID, p.ID, a.ID)
			if err != nil {
				t.Fatal(err)
			}
			journalID, err := result.LastInsertId()
			if err != nil {
				t.Fatal(err)
			}
			if _, err := h.db.Exec(`INSERT INTO journal_lines (entry_id, account, debit_minor, credit_minor)
				VALUES (?, 'bank', 12000, 0), (?, 'accounts_receivable', 0, 12000)`, journalID, journalID); err != nil {
				t.Fatal(err)
			}
			if _, err := h.db.Exec(`UPDATE proposals SET status = 'posted' WHERE id = ?`, p.ID); err != nil {
				t.Fatal(err)
			}
			if tc.settle {
				if _, err := h.db.Exec(`UPDATE invoices SET status = 'settled' WHERE tenant_id = 'tenant-a' AND invoice_id = ?`, tc.invoiceID); err != nil {
					t.Fatal(err)
				}
			}
			report, err := h.svc.VerifyLedger(context.Background())
			if err != nil {
				t.Fatal(err)
			}
			if len(report.Problems) != 1 || !strings.Contains(report.Problems[0], tc.problem) {
				t.Fatalf("problems = %v, want %q", report.Problems, tc.problem)
			}
		})
	}
}
